INSERT INTO {database}.{schema}.DEMO_CLAIMS_UNLABELED (CLAIM_SUMMARY, INCIDENT_CHANNEL, CUSTOMER_SEGMENT)
VALUES
    ('A customer who opened their policy just eleven days ago called to report that all four wheels and tires were stolen from their 2023 BMW X5 overnight in their apartment complex parking lot, but the complex''s security camera footage shows no activity near the vehicle during the timeframe provided. The claimant became evasive when asked for the police report number and mentioned they had recently increased their comprehensive coverage limits the day before the alleged theft occurred.', 'phone', 'new_customer'),
    ('A customer who opened their policy just eleven days ago called to report that all four wheels and tires were stolen from their 2023 BMW X5 overnight in their apartment complex parking lot, though the complex''s security camera footage conveniently shows the area was obscured by a delivery truck during the alleged timeframe. The claimant was unable to provide a police report number and became evasive when asked about prior insurance history or whether the vehicle had any existing mechanical issues.', 'phone', 'new_customer'),
    ('A customer who opened their policy just eleven days ago called to report that their 2022 BMW X5 was allegedly stolen from a grocery store parking lot overnight, though they were unable to explain why the vehicle was parked there for over twelve hours or provide any surveillance footage from the well-monitored lot. The claimant became evasive when asked about their current financial situation and could not produce the second set of keys for the vehicle.', 'phone', 'new_customer'),
    ('A customer who opened their policy just eleven days ago has filed a web claim for a total loss of $47,000 in high-end electronics and designer clothing due to an alleged apartment burglary, yet the police report notes no signs of forced entry and the claimant was unable to provide any original receipts or proof of ownership. The listed items appear to significantly exceed what would be expected given the claimant''s reported income and modest rental unit.', 'web', 'new_customer'),
    ('A customer who opened their policy just eleven days ago has filed a web claim for a total loss of $47,000 in high-end electronics and designer clothing from an alleged apartment burglary, yet the police report notes no signs of forced entry and the claimant was unable to provide any original receipts or proof of ownership. The claimant''s listed address corresponds to a short-term rental unit, and a prior inquiry reveals two similar theft claims filed with different carriers in the past eighteen months.', 'web', 'new_customer'),
    ('A customer who opened their policy just eleven days ago is filing a claim through their agent for a total loss house fire that allegedly destroyed $180,000 worth of recently purchased electronics and designer furniture, though neighbors report the home appeared mostly unfurnished prior to the incident. The fire marshal''s preliminary report notes multiple points of origin and the absence of any personal items such as photographs, documents, or clothing in the debris.', 'agent', 'new_customer'),
    ('A customer who opened their policy just eleven days ago is filing a claim through their agent for a total loss house fire that allegedly started from a space heater, though the fire marshal''s preliminary report notes the home had been largely emptied of personal belongings prior to the blaze. The claimant is pressing for an expedited payout and has provided receipts for high-value electronics and furniture that appear to have been printed recently, with several listing retailers that have been closed for over two years.', 'agent', 'new_customer'),
    ('A customer who opened their policy just eleven days ago is filing a claim through their agent for a total loss house fire that occurred while they were conveniently out of town, with neighbors reporting no signs of smoke or fire alarms sounding before the structure was fully engulfed. The agent noted the customer had specifically requested maximum coverage limits and declined any deductible increases during the initial policy setup, and the fire marshal''s preliminary report indicates multiple points of origin.', 'agent', 'new_customer'),
    ('A customer who opened their policy just eleven days ago is filing a claim through their agent for a total loss house fire that occurred while they were conveniently out of town, with neighbors reporting no signs of smoke or fire alarms sounding before the structure was fully engulfed. The agent noted the customer had specifically requested maximum coverage limits and declined any deductible increases during the initial policy setup, and the fire marshal''s preliminary report indicates multiple points of origin.', 'agent', 'new_customer'),
    ('A customer who opened their policy just eleven days ago is filing a claim through their agent for a total loss house fire, but the fire marshal''s preliminary report notes the home had been cleared of all personal valuables and family photos prior to the blaze. The claimant is also requesting an expedited payout due to alleged urgent relocation needs, despite having already signed a lease on a new apartment three days before the fire occurred.', 'agent', 'new_customer'),
    ('A customer who opened their policy just nine days ago has filed a web claim for a total loss of $47,000 in high-end electronics and designer clothing due to an alleged apartment burglary, yet the police report notes no signs of forced entry and the claimant was unable to provide any original receipts or proof of ownership. The listed items appear to significantly exceed what would be expected given the claimant''s reported income and modest rental unit.', 'web', 'new_customer'),
    ('A customer who opened their policy just nine days ago is filing a claim through our web portal for a supposedly stolen $8,200 mountain bike from their locked garage, but the police report was filed three days after the alleged theft and the customer cannot provide any purchase receipt or proof of ownership beyond a single blurry photo.', 'web', 'new_customer'),
    ('A deer ran into the side of my 2024 Honda CR-V while I was driving on Route 9 last Thursday evening, shattering the rear passenger window and leaving significant dent damage along the right quarter panel. I just purchased this vehicle three weeks ago and set up my policy at that time, and my agent suggested I file this claim right away.', 'agent', 'new_customer'),
    ('A new policyholder called to report that a severe hailstorm two days ago shattered three skylights and cracked multiple roof tiles on her recently purchased townhome, resulting in water intrusion that damaged the upstairs hallway ceiling and a bedroom closet. She noted that she had just activated her homeowners policy three weeks prior and has already contacted a roofing contractor for a temporary tarp installation.', 'phone', 'new_customer'),
    ('A new policyholder called to report that a severe hailstorm two days ago shattered three skylights and cracked multiple roof tiles on her recently purchased townhome, resulting in water intrusion that damaged the upstairs hallway ceiling and a bedroom closet. She noted that she had just activated her homeowners policy three weeks prior and wanted to understand the claims process before scheduling any emergency repairs.', 'phone', 'new_customer'),
    ('A new policyholder called to report that a severe hailstorm two days ago shattered three skylights and cracked multiple roof tiles on her recently purchased townhome, resulting in water intrusion that damaged the upstairs hallway ceiling and a bedroom closet. She noted that she had just activated her homeowners policy three weeks prior and wanted to understand the claims process, as this is her first time filing.', 'phone', 'new_customer'),
    ('A new policyholder called to report that a severe hailstorm two days ago shattered three skylights and cracked multiple roof tiles on her recently purchased townhome, resulting in water intrusion that damaged the upstairs hallway ceiling and a bedroom closet. She noted that she had just activated her homeowners policy three weeks prior and wanted to understand the claims process, as this is her first time filing.', 'phone', 'new_customer'),
    ('A new policyholder called to report that a severe hailstorm two days ago shattered three skylights and damaged the roof shingles on her recently purchased townhome, resulting in water intrusion that warped the hardwood flooring in the upstairs hallway and master bedroom. She noted that she had only activated her homeowners policy eleven days prior to the storm and is requesting an adjuster visit as soon as possible.', 'phone', 'new_customer'),
    ('A new policyholder called to report that his detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The customer noted he discovered the break-in this morning when he saw the garage''s side door had been pried open and has already filed a police report.', 'phone', 'new_customer'),
    ('A new policyholder called to report that his detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The customer noted he discovered the break-in this morning when he saw the garage''s side door had been pried open and has already filed a police report.', 'phone', 'new_customer'),
    ('A new policyholder called to report that his detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The customer noted he discovered the break-in this morning when he saw the garage''s side door had been pried open and has already filed a police report.', 'phone', 'new_customer'),
    ('A new policyholder called to report that his detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The customer noted he discovered the break-in this morning when he saw the garage''s side door had been pried open and immediately filed a police report before contacting us.', 'phone', 'new_customer'),
    ('A new policyholder called to report that his detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The customer noted he had only activated his homeowners policy eleven days prior and discovered the break-in when he noticed the garage''s side door had been pried open this morning.', 'phone', 'new_customer'),
    ('A new policyholder called to report that his detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The customer noted he had only activated his homeowners policy eleven days prior and discovered the break-in when he noticed the garage''s side door had been pried open this morning.', 'phone', 'new_customer'),
    ('A new policyholder called to report that she slipped on a wet floor at a grocery store three days ago, sustaining a fractured wrist and severe bruising to her left hip, and is seeking coverage for emergency room costs and follow-up orthopedic appointments. She mentioned that the store manager acknowledged the spill had not been cleaned up despite a prior customer complaint, and she has obtained a copy of the incident report filed at the location.', 'phone', 'new_customer'),
    ('A new policyholder called to report that she slipped on a wet floor at a grocery store three days ago, sustaining a fractured wrist and severe bruising to her left hip, and is seeking coverage for emergency room costs and follow-up orthopedic appointments. She mentioned that the store manager acknowledged the spill had not been cleaned up despite being reported by another customer twenty minutes prior to her fall.', 'phone', 'new_customer'),
    ('A new policyholder called to report that she sustained a fractured collarbone and severe bruising after a ceiling-mounted light fixture fell on her while dining at a restaurant last Saturday evening. She is seeking coverage for emergency room treatment, follow-up orthopedic visits, and lost wages during her expected six-week recovery period.', 'phone', 'new_customer'),
    ('A new policyholder called to report that she sustained a fractured collarbone and severe bruising after a ceiling-mounted light fixture fell on her while dining at a restaurant last Saturday evening. She is seeking coverage for emergency room treatment, follow-up orthopedic visits, and lost wages during her expected six-week recovery period.', 'phone', 'new_customer'),
    ('A new policyholder called to report that she sustained a fractured collarbone and severe bruising after a ceiling-mounted light fixture fell on her while dining at a restaurant last Saturday evening. She is seeking coverage for emergency room treatment, follow-up orthopedic visits, and lost wages during her expected six-week recovery period.', 'phone', 'new_customer'),
    ('A new policyholder called to report that she sustained a fractured collarbone and severe bruising after a ceiling-mounted light fixture fell on her while dining at a restaurant last Saturday evening. She is seeking coverage for emergency room treatment, follow-up orthopedic visits, and lost wages during her expected six-week recovery period.', 'phone', 'new_customer'),
    ('A new policyholder contacted their agent three weeks after binding coverage to report that a severe hailstorm had shattered two skylights and damaged the roof shingles on their recently purchased colonial home, resulting in water intrusion that warped the hardwood flooring in the upstairs hallway and master bedroom. The agent filed the claim on the customer''s behalf and arranged for an emergency tarp service to prevent further water damage until an adjuster could inspect the property.', 'agent', 'new_customer'),
    ('A new policyholder contacted their agent three weeks after binding coverage to report that a severe hailstorm had shattered two skylights and damaged the roof shingles on their recently purchased home, resulting in water intrusion that warped the hardwood flooring in the upstairs hallway and master bedroom. The agent filed the claim on the customer''s behalf and arranged for an emergency tarp service to prevent further water damage until an adjuster could inspect the property.', 'agent', 'new_customer'),
    ('A new policyholder contacted their agent three weeks after binding coverage to report that a severe hailstorm had shattered two skylights and damaged the roof shingles on their recently purchased home, resulting in water intrusion that warped the hardwood flooring in the upstairs hallway and master bedroom. The agent filed the claim on the customer''s behalf and arranged for an emergency tarp service to prevent further water damage until an adjuster could inspect the property.', 'agent', 'new_customer'),
    ('A new policyholder contacted their agent three weeks after binding coverage to report that a severe hailstorm had shattered two skylights and damaged the roof shingles on their recently purchased home, resulting in water intrusion that warped the hardwood flooring in the upstairs hallway. The agent filed the claim on the customer''s behalf and arranged for an emergency tarp service to prevent further water damage until an adjuster could inspect the property.', 'agent', 'new_customer'),
    ('A new policyholder contacted their agent to report that a severe hailstorm damaged the roof, gutters, and exterior siding of their recently purchased home, with water now leaking into the upstairs bedroom through compromised shingles. The agent filed the claim on the customer''s behalf and arranged for an emergency tarp installation to prevent further interior water damage while an adjuster is scheduled.', 'agent', 'new_customer'),
    ('A new policyholder emailed to file a claim after a three-vehicle chain-reaction collision on I-95, but the police report has not yet been released and the other two drivers'' insurance information was not exchanged at the scene due to the confusion. The customer is requesting guidance on how to proceed without the accident report and is unable to confirm which of the other parties'' insurers should be contacted for subrogation.', 'email', 'new_customer'),
    ('A new policyholder emailed to file a claim for water damage to their recently purchased condominium, but the closing documents, proof of ownership transfer, and the original home inspection report have not yet been received from the title company, delaying verification of coverage effective dates. The claim is further complicated by a dispute between the condo association''s master policy insurer and the individual unit owner''s carrier over which party is responsible for damage to shared plumbing infrastructure that caused the leak.', 'email', 'new_customer'),
    ('A new policyholder emailed to file a claim for water damage to their recently purchased condominium, but the closing documents, proof of ownership transfer, and the original home inspection report have not yet been received from the title company, delaying verification of coverage effective dates. The claim is further complicated by a dispute between the condo association''s master policy insurer and the individual unit owner''s carrier over which party is responsible for damage to shared plumbing infrastructure within the walls.', 'email', 'new_customer'),
    ('A new policyholder emailed to file a liability claim after a three-vehicle chain-reaction collision in a parking garage, but the police report was never completed at the scene and the third driver''s insurance information was not exchanged, leaving critical documentation gaps that are complicating fault determination. The customer has provided their own written account and dashcam footage but is requesting guidance on how to proceed without the missing third-party details.', 'email', 'new_customer'),
    ('A new policyholder emailed to file a liability claim after a three-vehicle chain-reaction collision in a parking garage, but the police report was never completed at the scene and the third driver''s insurance information was not exchanged, leaving critical documentation gaps that are complicating fault determination. The customer has provided their own written account and dashcam footage but is requesting guidance on how to proceed without the missing third-party details.', 'email', 'new_customer'),
    ('A new policyholder emailed to file a liability claim after a three-vehicle chain-reaction collision in a shopping center parking lot, but the police report was never completed at the scene and the third driver''s insurance information was not exchanged. The customer is requesting guidance on how to proceed without the missing documentation and is unsure which of the three parties'' insurers should be handling the property damage assessments.', 'email', 'new_customer'),
    ('A new policyholder emailed to report a three-vehicle chain-reaction collision on Interstate 40, involving drivers insured by three different carriers, but was unable to provide the police report number or the other parties'' insurance details as the responding officer only issued a verbal case reference at the scene. The customer is requesting guidance on how to proceed with the claim given that the accident report from the county sheriff''s office has a 10-14 business day processing delay and liability determination requires coordination among all three insurers.', 'email', 'new_customer'),
    ('A new policyholder emailed to report a three-vehicle chain-reaction collision on Interstate 40, involving drivers insured by three different carriers, but was unable to provide the police report number or the other parties'' insurance details as the responding officer only issued a verbal case reference at the scene. The customer is requesting guidance on how to proceed with the claim given that the police department has informed them the written accident report will not be available for 10-14 business days.', 'email', 'new_customer'),
    ('A new policyholder reported through the online claims portal that their detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The customer noted that the garage lock had been cut with bolt cutters and provided a police report filed earlier that morning.', 'web', 'new_customer'),
    ('A new policyholder reported through their agent that their detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The police report indicates forced entry through a side door, and the customer noted they had only activated their homeowners policy three weeks prior to the incident.', 'agent', 'new_customer'),
    ('A new policyholder reported through their agent that their detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The police report indicates forced entry through a side door, and the customer noted they had only activated their homeowners policy three weeks prior to the incident.', 'agent', 'new_customer'),
    ('A new policyholder reported through their agent that their detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The police report indicates forced entry through a side door, and the customer noted they had only activated their homeowners policy three weeks prior to the incident.', 'agent', 'new_customer'),
    ('A new policyholder reported through their agent that their detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The police report indicates forced entry through a side door, and the customer noted they had only activated their homeowners policy three weeks prior to the incident.', 'agent', 'new_customer'),
    ('A new policyholder reported through their agent that their detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The police report indicates forced entry through a side door, and the customer noted they had only activated their homeowners policy three weeks prior to the incident.', 'agent', 'new_customer'),
    ('A new policyholder reported through their agent that their detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The police report indicates forced entry through a side door, and the customer noted they had only activated their homeowners policy three weeks prior to the incident.', 'agent', 'new_customer');
INSERT INTO {database}.{schema}.DEMO_CLAIMS_UNLABELED (CLAIM_SUMMARY, INCIDENT_CHANNEL, CUSTOMER_SEGMENT)
VALUES
    ('A new policyholder reported through their agent that their detached garage was broken into overnight, with thieves stealing a riding lawn mower, a set of power tools, and two mountain bikes valued at approximately $4,800 total. The police report indicates the padlock was cut and security camera footage from a neighbor''s property captured an unidentified individual loading items into a dark-colored pickup truck.', 'agent', 'new_customer'),
    ('A new policyholder submitted a web claim reporting that a severe hailstorm damaged the roof and skylights of their recently purchased home, resulting in water intrusion that warped hardwood flooring in the upstairs hallway and master bedroom. The customer noted they had only activated their homeowners policy three weeks prior and included timestamped photos of the damage along with a local weather service alert confirming the storm.', 'web', 'new_customer'),
    ('A new policyholder submitted a web claim reporting that a severe hailstorm damaged the roof and skylights of their recently purchased home, resulting in water intrusion that warped hardwood flooring in the upstairs hallway and master bedroom. The customer noted they had only activated their homeowners policy three weeks prior to the storm event.', 'web', 'new_customer'),
    ('A new policyholder submitted a web claim reporting that a severe hailstorm damaged the roof and skylights of their recently purchased home, resulting in water intrusion that warped hardwood floors in the upstairs hallway and master bedroom. The customer noted they had only activated their homeowners policy three weeks prior and included timestamped photos of the damage along with a local weather service alert confirming the storm.', 'web', 'new_customer'),
    ('A new policyholder was struck by a falling shelf unit at a home improvement store three weeks after enrolling in a personal injury protection plan, sustaining a fractured collarbone and deep lacerations to the left arm requiring surgical intervention. The claim was filed through the customer''s assigned agent, who documented the incident report and emergency room records for processing.', 'agent', 'new_customer'),
    ('A new policyholder was struck by a falling shelf unit at a home improvement store three weeks after enrolling in a personal injury protection plan, sustaining a fractured collarbone and severe bruising to the left shoulder. The claim was filed through the customer''s assigned agent, who documented the incident report and emergency room records from the treating hospital.', 'agent', 'new_customer'),
    ('A new policyholder was struck by a falling shelf unit at a home improvement store three weeks after enrolling in a personal injury protection plan, sustaining a fractured collarbone and severe bruising to the left shoulder. The claim was filed through the customer''s assigned insurance agent, who documented the incident report and emergency room records from the treating hospital.', 'agent', 'new_customer'),
    ('A new policyholder was struck by a falling shelf unit at a home improvement store three weeks after obtaining their policy, sustaining a fractured collarbone and severe bruising to the left shoulder. The claim was filed through their insurance agent, who documented the incident report and emergency room records for the bodily injury liability review.', 'agent', 'new_customer'),
    ('A new policyholder''s 2023 Kia Sportage was rear-ended at a red light on Route 9 by a distracted driver, resulting in a crushed rear bumper, damaged tailgate, and misaligned rear axle. The claim was filed through their assigned agent the following morning, and the customer reported persistent neck stiffness from the impact.', 'agent', 'new_customer'),
    ('A policy purchased online just eleven days ago is now the subject of a claim by the new policyholder, who reports that their recently acquired 2023 BMW X5 was stolen from a grocery store parking lot overnight, despite the vehicle''s GPS tracker showing no movement from the insured''s home address during the alleged timeframe. The claimant has been unable to provide a second key fob and became evasive when asked about the vehicle''s current loan balance, which our preliminary check reveals exceeds the car''s market value by approximately $14,000.', 'web', 'new_customer'),
    ('A policy purchased online just eleven days ago is now the subject of a claim by the new policyholder, who reports that their recently acquired 2023 luxury watch collection, valued at $47,000, was stolen from an unlocked vehicle while parked overnight in their driveway, with no surveillance footage available despite the claimant mentioning a home security system during the application process. The claimant has been unable to provide original purchase receipts and instead submitted only screenshots of online listings for similar items.', 'web', 'new_customer'),
    ('A premium policyholder submitted a web claim for $187,000 in water damage to their recently renovated lakefront property, but the adjuster noted the homeowner had tripled their coverage limits just eleven days before the alleged pipe burst and neighbors reported seeing the residence unoccupied for several weeks. The claimant''s contractor brother-in-law provided the sole repair estimate, which included replacement of items not typically affected by the described ground-floor plumbing failure.', 'web', 'premium'),
    ('A premium policyholder submitted a web claim for $187,000 in water damage to their recently renovated lakefront property, but the adjuster noted the homeowner had tripled their coverage limits just eleven days before the alleged pipe burst, and the plumber''s invoice appears to reference work completed two weeks prior to the reported loss date. Neighbors also reported seeing the claimant loading furniture into a rental truck the evening before the incident was supposedly discovered.', 'web', 'premium'),
    ('A premium policyholder submitted a web claim for $187,000 in water damage to their recently renovated lakefront property, but the adjuster noted the homeowner had tripled their coverage limits just eleven days before the alleged pipe burst, and the plumber''s invoice appears to reference work completed two weeks prior to the reported loss date. Neighbors also reported seeing the claimant loading furniture into a rental truck the evening before the incident was supposedly discovered.', 'web', 'premium'),
    ('A premium policyholder submitted a web claim for $187,000 in water damage to their recently renovated lakefront property, but the adjuster noted the homeowner had tripled their coverage limits just eleven days before the alleged pipe burst, and the plumber''s invoice appears to reference work completed two weeks prior to the reported loss date. Neighbors also reported seeing the claimant loading furniture into a rental truck the evening before the incident was supposedly discovered.', 'web', 'premium'),
    ('A premium policyholder submitted a web claim for $187,000 in water damage to their recently renovated lakefront property, but the adjuster noted the homeowner had tripled their coverage limits just eleven days before the alleged pipe burst, and the plumber''s invoice appears to reference work completed two weeks prior to the reported loss date. Neighbors also reported seeing the claimant loading furniture into a rental truck the evening before the incident was supposedly discovered.', 'web', 'premium'),
    ('After last Thursday''s severe thunderstorm, a large oak tree in our neighbor''s yard was uprooted and crashed through our garage roof, crushing one vehicle inside and causing extensive structural damage to the attached mudroom. We just purchased this home six weeks ago and activated our policy on closing day, and I''m submitting photos and the initial contractor assessment via this email for your review.', 'email', 'new_customer'),
    ('After last Thursday''s severe thunderstorm, a large oak tree in our neighbor''s yard was uprooted and crashed through our garage roof, crushing one vehicle inside and causing extensive structural damage to the garage and adjacent mudroom. We purchased our homeowner''s policy just six weeks ago when we closed on the house, and I''m submitting photos of the damage along with the emergency tarp installation receipt from the contractor we called that evening.', 'email', 'new_customer'),
    ('After last week''s severe thunderstorm brought down a large oak tree onto our garage roof, we discovered extensive structural damage to the garage and water intrusion into the attached mudroom. We purchased our homeowner''s policy just six weeks ago and are submitting this claim via email along with photos of the damage and a preliminary estimate from a local contractor.', 'email', 'new_customer'),
    ('After last week''s severe thunderstorm brought down a large oak tree onto our garage roof, we discovered extensive structural damage to the garage and water intrusion into the attached mudroom; we just purchased this home and closed on it three weeks ago. I''ve attached photos of the damage and the initial estimate from a local contractor to this email for your review.', 'email', 'new_customer'),
    ('After last week''s severe thunderstorm knocked a large oak tree onto our garage roof, we discovered extensive structural damage to the garage and water intrusion into the attached mudroom that has warped the hardwood flooring and soaked through the drywall. We purchased our homeowner''s policy just six weeks ago and are submitting this claim via email along with photos and a preliminary estimate from our contractor.', 'email', 'new_customer'),
    ('Called in to report that my parked car was struck by a delivery truck backing out of a loading zone at the shopping center on Elm Street yesterday afternoon, crushing the rear bumper and shattering the taillight assembly. I just started this policy three weeks ago and the truck driver''s company is disputing fault, so I need to understand how my coverage applies.', 'phone', 'new_customer'),
    ('Called in to report that my parked car was struck by a delivery truck backing out of a loading zone at the shopping center on Elm Street yesterday afternoon, resulting in a crushed rear bumper and shattered taillight on my 2024 Hyundai Tucson. I just purchased the vehicle three weeks ago and activated my policy on the same day, so this is my first time filing a claim.', 'phone', 'new_customer'),
    ('Called in to report that my parked car was struck by a delivery truck backing out of a loading zone at the shopping center on Elm Street yesterday afternoon, resulting in significant damage to the rear bumper and tailgate of my 2023 Honda CR-V. I just purchased the policy last week and this is my first time filing a claim, so I''m not sure what documentation you''ll need from me.', 'phone', 'new_customer'),
    ('Called in to report that my parked car was struck by a delivery truck backing out of a neighboring driveway yesterday afternoon, crushing the driver''s side rear quarter panel and shattering the taillight. I just started my policy three weeks ago and this is my first time filing any kind of insurance claim, so I''m not sure what documentation you''ll need from me.', 'phone', 'new_customer'),
    ('Called to report that my apartment was broken into while I was at work yesterday; the back door lock was forced open and my laptop, gaming console, two designer watches, and approximately $300 in cash were taken from the bedroom. I just started this policy three weeks ago and haven''t had a chance to do a home inventory yet, but I do have receipts for most of the electronics.', 'phone', 'new_customer'),
    ('Caller reported that while backing out of a grocery store parking space yesterday evening, she struck a concrete bollard she didn''t see in her rearview mirror, cracking her rear bumper and damaging the taillight assembly on her 2024 Hyundai Tucson. As a new policyholder who just activated her coverage three weeks ago, she wanted to confirm her deductible amount and understand the next steps for filing her first claim.', 'phone', 'new_customer'),
    ('Caller reported that while backing out of a grocery store parking space yesterday evening, she struck a concrete bollard she didn''t see in her side mirror, cracking the rear bumper and denting the quarter panel of her 2024 Kia Sportage. As a new policyholder who just activated her coverage three weeks ago, she wanted to confirm her deductible amount and understand the next steps for filing her first claim.', 'phone', 'new_customer'),
    ('Caller reported that while driving through a construction zone on Route 9, a piece of unsecured rebar flew off a flatbed truck ahead and punctured the front grille and radiator of her 2021 Hyundai Tucson, causing the engine to overheat and requiring an immediate tow. She obtained the truck''s license plate number and has dashcam footage of the incident, and is requesting coverage for towing, radiator replacement, and a rental vehicle while repairs are completed.', 'phone', 'standard'),
    ('Caller reported that while driving through a construction zone on Route 9, a piece of unsecured rebar flew off a flatbed truck ahead and punctured the front grille and radiator of her 2021 Hyundai Tucson, causing the engine to overheat and requiring an immediate tow. She stated she was able to capture dashcam footage of the incident and has already obtained a repair estimate of $4,200 from her local body shop.', 'phone', 'standard'),
    ('Caller reported that while driving through a construction zone on Route 9, a piece of unsecured rebar flew off a flatbed truck ahead and punctured the front grille and radiator of her 2021 Hyundai Tucson, causing the engine to overheat and requiring an immediate tow. She stated she was able to capture the truck''s license plate and has dashcam footage of the incident, and is requesting coverage for towing, radiator replacement, and a rental vehicle while repairs are completed.', 'phone', 'standard'),
    ('Caller reported that while driving through a construction zone on Route 9, a piece of unsecured rebar flew off a flatbed truck ahead and punctured the front grille and radiator of her 2021 Hyundai Tucson, causing the engine to overheat and requiring an immediate tow. She stated she was able to get the truck''s license plate number and has dashcam footage of the incident, and is requesting coverage for towing, radiator replacement, and a rental vehicle while repairs are completed.', 'phone', 'standard'),
    ('Caller reported that while driving through a construction zone on Route 9, a piece of unsecured rebar flew off a flatbed truck ahead and punctured the front grille and radiator of her 2021 Hyundai Tucson, causing the engine to overheat and requiring an immediate tow. She stated she was unable to identify the truck''s license plate but has dashcam footage of the incident and is requesting coverage for towing, radiator replacement, and a rental vehicle while repairs are completed.', 'phone', 'standard'),
    ('Claimant called to report a slip and fall incident at a grocery store on March 14th, stating she lost her footing on a wet floor near the produce section and fractured her left wrist upon impact. She was transported by ambulance to St. Mary''s Medical Center where X-rays confirmed the fracture, and she is requesting coverage for emergency room costs, follow-up orthopedic visits, and lost wages during her recovery period.', 'phone', 'standard'),
    ('Claimant called to report a slip and fall incident at a grocery store where she stepped on a wet floor near the produce section, resulting in a fractured left wrist and bruised tailbone requiring emergency room treatment and a follow-up orthopedic consultation. She states there were no wet floor signs posted at the time of the accident and has submitted initial medical bills totaling approximately $4,200.', 'phone', 'standard'),
    ('Claimant called to report a slip and fall incident at a grocery store where she stepped on a wet floor near the produce section, resulting in a fractured left wrist and bruised tailbone requiring emergency room treatment and a follow-up orthopedic consultation. She states there were no wet floor signs posted at the time of the accident and has submitted initial medical bills totaling approximately $4,200.', 'phone', 'standard'),
    ('Claimant called to report a slip and fall incident at a grocery store where she stepped on a wet floor near the produce section, resulting in a fractured left wrist and bruised tailbone requiring emergency room treatment and a follow-up orthopedic consultation. She states there were no wet floor signs posted at the time of the accident and has submitted initial medical bills totaling approximately $4,200.', 'phone', 'standard'),
    ('Claimant called to report a three-vehicle chain-reaction collision on Interstate 40, but is unable to provide the other two drivers'' insurance information as the responding officer''s accident report has not yet been released by the county sheriff''s department. The claimant stated he has been calling the records office daily for two weeks and was advised to file his claim now to avoid missing any deadlines.', 'phone', 'standard'),
    ('Claimant called to report a three-vehicle chain-reaction collision on Interstate 40, but is unable to provide the other two drivers'' insurance information as the responding officer''s accident report has not yet been released by the county sheriff''s department. The claimant stated he has contacted the sheriff''s office multiple times and was told the report is delayed due to a backlog, and he is requesting guidance on how to proceed with his property damage claim in the interim.', 'phone', 'standard'),
    ('Claimant called to report a three-vehicle chain-reaction collision on Interstate 40, but is unable to provide the other two drivers'' insurance information as the responding officer''s accident report has not yet been released by the county sheriff''s department. The insured stated he has been trying to obtain the report for over two weeks and requested we proceed with his claim while he continues to follow up on the missing documentation.', 'phone', 'standard'),
    ('Claimant called to report a three-vehicle chain-reaction collision on Interstate 40, but is unable to provide the police report number or contact information for the third driver, whose insurance carrier remains unidentified at this time. Our adjuster has requested the claimant obtain a copy of the accident report from the county sheriff''s office and provide any dashcam footage to help establish liability across all involved parties.', 'phone', 'standard'),
    ('Claimant called to report a three-vehicle chain-reaction collision on Interstate 40, but is unable to provide the police report number or contact information for the third driver, whose insurance carrier remains unidentified at this time. The claimant states the responding officer''s badge number was not recorded and the accident report has not yet been filed with the county, complicating liability determination across all involved parties.', 'phone', 'standard'),
    ('Claimant called to report a three-vehicle chain-reaction collision on Interstate 40, but is unable to provide the police report number or contact information for the third driver, whose insurance carrier remains unidentified at this time. The claimant states the responding officer''s badge number was not recorded and the accident report has not yet been filed with the county, complicating liability determination across all involved parties.', 'phone', 'standard'),
    ('Claimant called to report a total loss of a 2019 Honda Accord allegedly stolen from a grocery store parking lot overnight, but surveillance footage from the store shows the vehicle leaving the lot under its own power at 2:47 AM, and the claimant''s phone GPS data places them at the vehicle''s location during that time. The claimant has also made three prior theft claims with different insurers over the past five years, each involving vehicles with outstanding loan balances exceeding their market value.', 'phone', 'standard'),
    ('Claimant called to report a total loss of a 2019 Honda Accord allegedly stolen from a grocery store parking lot overnight, but surveillance footage from the store shows the vehicle leaving the lot under its own power at 2:47 AM, and the claimant''s phone GPS data places them at the vehicle''s location during that time. The claimant has also made three prior theft claims with different insurers over the past five years, each involving vehicles with outstanding loan balances exceeding their market value.', 'phone', 'standard'),
    ('Claimant called to report a total loss of a 2019 Honda Accord allegedly stolen from a grocery store parking lot overnight, but surveillance footage from the store shows the vehicle leaving the lot under its own power at 2:47 AM, and the claimant''s phone GPS data places them at the vehicle''s location during that time. The policy was upgraded from liability-only to comprehensive coverage just eleven days before the reported theft, and the claimant has made three prior theft claims with different insurers over the past five years.', 'phone', 'standard'),
    ('Claimant called to report a total loss of a 2019 Honda Accord allegedly stolen from a grocery store parking lot overnight, but surveillance footage from the store shows the vehicle leaving the lot under its own power at 2:47 AM, and the claimant''s phone GPS data places them at the vehicle''s location during that time. The policy was upgraded from liability-only to comprehensive coverage just eleven days before the reported theft, and the claimant has made three prior theft claims with different insurers over the past six years.', 'phone', 'standard'),
    ('Claimant called to report a total loss of a 2019 Honda Accord allegedly stolen from a grocery store parking lot overnight, but surveillance footage from the store shows the vehicle was never parked there during the timeframe specified, and the claimant''s phone GPS data places them at a different location than stated. The policy was upgraded to comprehensive coverage just eleven days before the reported theft, and the claimant became notably evasive when the adjuster asked routine follow-up questions about the vehicle''s spare key.', 'phone', 'standard'),
    ('Claimant called to report that his locked garden shed was broken into overnight, and approximately $2,800 worth of power tools including a table saw, cordless drill set, and pressure washer were stolen. A police report has been filed and the claimant is gathering original purchase receipts for the missing items.', 'phone', 'standard'),
    ('Claimant called to report that his locked garden shed was broken into overnight, with thieves stealing a riding lawn mower, a pressure washer, and approximately $800 worth of power tools. The police report has been filed and the claimant noted that the padlock appeared to have been cut with bolt cutters.', 'phone', 'standard');
INSERT INTO {database}.{schema}.DEMO_CLAIMS_UNLABELED (CLAIM_SUMMARY, INCIDENT_CHANNEL, CUSTOMER_SEGMENT)
VALUES
    ('Claimant called to report that his locked storage unit at a commercial facility was broken into overnight, with thieves cutting the padlock and stealing approximately $4,200 worth of power tools, camping equipment, and seasonal sporting goods. The facility''s security cameras captured footage of two individuals loading items into a dark-colored van around 3:15 AM, and a police report has been filed with the local sheriff''s department.', 'phone', 'standard'),
    ('Claimant called to report that his locked storage unit at a commercial facility was broken into overnight, with thieves cutting the padlock and stealing approximately $4,200 worth of power tools, camping equipment, and seasonal sporting goods. The facility''s security cameras were non-functional at the time, and the claimant has provided a police report along with purchase receipts for the majority of the missing items.', 'phone', 'standard'),
    ('Claimant called to report that she slipped on a wet floor inside a grocery store last Saturday, landing on her right hip and sustaining a hairline fracture that required emergency room treatment and a follow-up with an orthopedic specialist. She is requesting coverage for medical expenses, including the ER visit, imaging, and ongoing physical therapy sessions recommended by her doctor.', 'phone', 'standard'),
    ('Claimant called to report that while driving through a construction zone on Route 9, a piece of unsecured rebar flew off a flatbed truck ahead and punctured the front grille and radiator of his 2021 Hyundai Tucson, causing the engine to overheat and requiring a tow to the nearest repair facility. He obtained the truck''s license plate number and dashcam footage capturing the incident, and is seeking coverage for towing, radiator replacement, and a rental vehicle while repairs are completed.', 'phone', 'standard'),
    ('Claimant reported through their agent that all four high-end custom wheels and tires were stolen from their 2023 BMW M4 overnight, yet security camera footage from the gated community shows no unfamiliar vehicles entering or exiting during the timeframe provided. The claimant also increased their comprehensive coverage limits just three weeks prior to the reported theft and has been unable to provide receipts for the aftermarket wheels allegedly valued at $12,000.', 'agent', 'standard'),
    ('Claimant reported through their agent that all four high-end custom wheels and tires were stolen from their 2023 BMW M4 overnight, yet surveillance footage from the gated community shows no unfamiliar vehicles entering or exiting during the timeframe provided. The claimant also increased their comprehensive coverage limits just three weeks prior to the reported theft and has been unable to provide receipts for the aftermarket upgrades allegedly valued at $14,000.', 'agent', 'standard'),
    ('Claimant reported through their agent that all four high-end custom wheels and tires were stolen from their 2023 BMW X5 overnight in a gated community with 24-hour security, yet no surveillance footage captured any activity and the vehicle was found resting neatly on matching jack stands. The claimant has filed three similar theft claims across different insurers in the past two years, each time shortly after purchasing aftermarket upgrades.', 'agent', 'standard'),
    ('Claimant reported through their agent that all four high-end custom wheels and tires were stolen from their 2023 BMW X5 overnight in a gated community with 24-hour security, yet no surveillance footage exists and the security guard on duty has no record of any unusual activity. The claimant had increased their comprehensive coverage limits just eleven days before the alleged theft and was unable to provide purchase receipts for the aftermarket wheels valued at $14,200.', 'agent', 'standard'),
    ('Claimant reported through their agent that all four high-end custom wheels and tires were stolen from their vehicle overnight in a gated community with 24-hour security, yet no surveillance footage captured any suspicious activity and the security guard on duty reported nothing unusual during their rounds. The claimant had increased their comprehensive coverage limits just eleven days before the alleged theft and was unable to provide purchase receipts for the aftermarket wheels valued at $8,200.', 'agent', 'standard'),
    ('Claimant reported through their agent that all four high-end custom wheels and tires were stolen from their vehicle overnight in a gated community with 24-hour security, yet no surveillance footage captured any suspicious activity and the security guard on duty reported nothing unusual during their rounds. The claimant had increased their comprehensive coverage limits just eleven days before the alleged theft and was unable to provide purchase receipts for the aftermarket wheels valued at $8,200.', 'agent', 'standard'),
    ('Claimant reports sustaining a fractured collarbone and severe bruising after slipping on an unmarked wet floor at a grocery store on March 14th, requiring surgical intervention and six weeks of physical therapy. Claim was filed through their insurance agent following discharge from the hospital, with medical documentation and an incident report from the store manager included in the submission.', 'agent', 'standard'),
    ('Claimant reports sustaining a fractured collarbone and severe bruising after slipping on an unmarked wet floor at a grocery store on March 14th, requiring surgical intervention and six weeks of physical therapy. Claim was filed through their insurance agent following discharge from the hospital, with medical records and an incident report from the store manager submitted as supporting documentation.', 'agent', 'standard'),
    ('Claimant reports sustaining a fractured collarbone and severe bruising after slipping on an unmarked wet floor at a grocery store on March 8th, requiring surgical intervention and six weeks of physical therapy. Claim was filed through the customer''s insurance agent following discharge from the hospital, with medical records and an incident report from the store manager submitted as supporting documentation.', 'agent', 'standard'),
    ('Claimant reports sustaining a fractured collarbone and severe bruising after slipping on an unmarked wet floor at a grocery store on November 3rd, requiring surgical intervention and six weeks of physical therapy. Claim was filed through the customer''s insurance agent following discharge from the hospital, with medical records and an incident report from the store manager submitted as supporting documentation.', 'agent', 'standard'),
    ('Claimant reports sustaining a fractured collarbone and severe bruising after slipping on an unmarked wet floor at a grocery store on November 3rd, requiring surgical intervention and six weeks of physical therapy. Claim was filed through the customer''s insurance agent following discharge from the hospital, with medical records and an incident report from the store manager submitted as supporting documentation.', 'agent', 'standard'),
    ('Claimant reports sustaining a fractured wrist and severe bruising after slipping on an unmarked wet floor at a grocery store on March 14, 2024, and is seeking coverage for emergency room treatment, orthopedic follow-up visits, and lost wages during recovery. The claim was submitted via email with attached medical records from St. Luke''s Hospital and a witness statement from another shopper who observed the fall.', 'email', 'standard'),
    ('Claimant reports sustaining a fractured wrist and severe bruising after slipping on an unmarked wet floor at a grocery store on March 14th, resulting in emergency room treatment and six weeks of physical therapy. The claim, submitted via email with attached medical records and incident photos, seeks coverage for medical expenses totaling $8,740 and lost wages during the recovery period.', 'email', 'standard'),
    ('Claimant reports sustaining a fractured wrist and severe bruising after slipping on an unmarked wet floor at a grocery store on March 8th, resulting in emergency room treatment and six weeks of physical therapy. Medical bills and lost wages documentation were attached to the email submission for review.', 'email', 'standard'),
    ('Claimant reports sustaining a fractured wrist and severe bruising after slipping on an unmarked wet floor at a grocery store on November 3rd, requiring emergency room treatment and a follow-up orthopedic consultation. Medical bills totaling approximately $8,200 have been submitted along with photographs of the hazard and a witness statement from another shopper who observed the fall.', 'web', 'standard'),
    ('Claimant reports sustaining a fractured wrist and severe bruising after slipping on an unmarked wet floor at a grocery store on November 3rd, requiring emergency room treatment and a follow-up orthopedic consultation. The claim was filed through the customer''s insurance agent, and medical documentation along with an incident report from the store manager have been submitted for review.', 'agent', 'standard'),
    ('Claimant reports sustaining a fractured wrist and severe bruising after slipping on an unmarked wet floor at a grocery store on November 3rd, resulting in emergency room treatment and six weeks of physical therapy. Claim submitted online with attached medical records, incident photos, and a statement from a store employee who witnessed the fall.', 'web', 'standard'),
    ('Claimant reports sustaining a fractured wrist and severe bruising after slipping on an unmarked wet floor at a grocery store on November 3rd, resulting in emergency room treatment and six weeks of physical therapy. The claim, submitted via email with attached medical records and incident photos, seeks coverage for medical expenses totaling $14,200 and lost wages during the recovery period.', 'email', 'standard'),
    ('Claimant reports sustaining a fractured wrist and severe bruising after slipping on an unmarked wet floor at a grocery store on November 3rd, resulting in emergency room treatment and six weeks of physical therapy. The claim, submitted via email with attached medical records and incident photos, seeks coverage for medical expenses totaling $8,740 and lost wages during the recovery period.', 'email', 'standard'),
    ('Claimant submitted a web filing for a stolen 65-inch television and gaming console from their apartment, but the police report was filed 11 days after the alleged burglary, and the claimant was unable to provide any purchase receipts, serial numbers, or photos of the items despite claiming they were purchased new less than three months ago.', 'web', 'standard'),
    ('Claimant submitted a web filing for a stolen 65-inch television and home theater system valued at $4,200, but the police report was filed 11 days after the alleged burglary, and the claimant was unable to provide any purchase receipts, serial numbers, or photos of the items despite claiming they were purchased just three months ago.', 'web', 'standard'),
    ('Claimant submitted a web filing for a stolen 65-inch television and home theater system valued at $4,200, but the purchase receipts provided appear to be from a retailer that closed permanently eighteen months before the alleged purchase date. Neighbors report no signs of forced entry or unusual activity at the residence on the date of the claimed burglary, and the claimant has filed three similar theft claims with different carriers in the past two years.', 'web', 'standard'),
    ('Claimant submitted a web filing for a stolen laptop and high-end camera equipment from their vehicle, but the police report was filed 11 days after the alleged theft, and the claimant was unable to provide any purchase receipts or serial numbers despite claiming the items were purchased new just three months ago. The total claimed amount of $4,870 closely matches the claimant''s current outstanding credit card balance, and a social media post from the same week shows the claimant discussing plans to "get finances back on track."', 'web', 'standard'),
    ('Claimant submitted a web filing for a stolen laptop and high-end camera equipment from their vehicle, but the police report was filed 11 days after the alleged theft, and the claimant was unable to provide any purchase receipts or serial numbers despite claiming the items were purchased new just three months prior. The total claimed amount of $4,870 also closely matches the claimant''s current outstanding credit card balance, raising additional concerns about the timing and motivation of the claim.', 'web', 'standard'),
    ('Claimant submitted a web-based property damage claim involving a three-vehicle chain-reaction collision, but the police report lists conflicting accounts from each driver and the at-fault party''s insurance carrier has not yet provided their policy declarations page. The claimant has been unable to obtain a copy of the responding officer''s supplemental report due to an administrative backlog at the county records office, delaying liability determination.', 'web', 'standard'),
    ('Claimant submitted a web-based property damage claim involving a three-vehicle chain-reaction collision, but the police report lists conflicting accounts from each driver and the at-fault party''s insurance carrier has not yet provided their policy declarations page. The claimant has been unable to obtain a copy of the responding officer''s supplemental report due to an administrative backlog at the county records office, delaying liability determination.', 'web', 'standard'),
    ('Claimant submitted a web-based property damage claim involving a three-vehicle chain-reaction collision, but the police report lists conflicting driver information and the at-fault party''s insurance carrier has not responded to liability inquiries, leaving subrogation efforts stalled. The claimant has been unable to obtain a copy of the amended accident report from the county sheriff''s office despite multiple requests, further delaying resolution of coverage determination.', 'web', 'standard'),
    ('Claimant submitted a web-based property damage claim involving a three-vehicle chain-reaction collision, but the police report lists conflicting driver information and the at-fault party''s insurance carrier has not responded to liability inquiries, leaving subrogation efforts stalled. The insured has provided their own documentation, though the repair shop''s itemized estimate and the third party''s policy declarations page remain outstanding after multiple requests.', 'web', 'standard'),
    ('Claimant submitted a web-based property damage claim involving a three-vehicle chain-reaction collision, but the police report lists only two of the three drivers and the at-fault party''s insurance carrier has not yet acknowledged coverage, leaving liability allocation unresolved. The insured has provided their own photos and a witness statement, though the third-party vehicle owner''s information remains unverified due to an incomplete accident exchange form.', 'web', 'standard'),
    ('Claimant submitted a web-filed property damage claim involving a three-vehicle chain-reaction collision on Interstate 40, but the police report lists conflicting driver information and the at-fault party''s insurance carrier has not responded to liability inquiries, leaving subrogation efforts stalled. The claimant has been unable to obtain a signed witness statement from the third driver, and our adjuster is awaiting the corrected accident report before proceeding with coverage determination.', 'web', 'standard'),
    ('Claimant submitted an email reporting that all three of his family''s vehicles were stolen from their driveway on the same night while the home security cameras were conveniently "undergoing a firmware update," and he is requesting full replacement value on policies that were upgraded to comprehensive coverage just eleven days prior to the alleged thefts.', 'email', 'standard'),
    ('Claimant submitted an email reporting that all three of his recently purchased high-end mountain bikes were stolen from his locked garage overnight, yet the police report notes no signs of forced entry and the claimant''s neighbor reported seeing him loading bikes into an unmarked van the previous evening. The claim totals $14,200 and was filed just six weeks after the claimant significantly increased his personal property coverage limits.', 'email', 'standard'),
    ('Claimant submitted an email reporting that all three of his vehicles were stolen from his driveway on the same night while he was allegedly visiting family out of state, yet neighbors report seeing the vehicles being driven away by someone matching the claimant''s description. The police report was filed four days after the alleged theft, and the claimant had recently increased coverage limits on all three vehicles just two weeks prior to the incident.', 'email', 'standard'),
    ('Claimant''s agent submitted a liability claim involving a three-vehicle chain-reaction collision on Interstate 40, but the police report lists conflicting driver statements and the at-fault party''s insurance carrier has not yet acknowledged coverage, delaying the determination of primary and secondary liability among the involved parties. The agent is requesting an update on subrogation efforts and has noted that the claimant''s signed medical authorization form was lost during transfer between adjusters and needs to be re-executed.', 'agent', 'standard'),
    ('Claimant''s agent submitted a liability claim involving a three-vehicle chain-reaction collision on Interstate 40, but the police report lists conflicting driver statements and the at-fault party''s insurance carrier has not yet acknowledged coverage, delaying the subrogation process. The agent is requesting an interim update on fault determination and has noted that the claimant''s medical release forms from two treating facilities are still outstanding despite multiple follow-up attempts.', 'agent', 'standard'),
    ('Claimant''s agent submitted a liability claim involving a three-vehicle chain-reaction collision on Interstate 40, but the police report lists conflicting driver statements and the at-fault party''s insurance carrier has not yet acknowledged coverage, delaying the subrogation process. The agent is requesting an interim update on fault determination and has noted that the claimant''s medical release forms from two treating facilities are still outstanding despite multiple follow-up attempts.', 'agent', 'standard'),
    ('Claimant''s agent submitted a liability claim involving a three-vehicle chain-reaction collision on Interstate 40, but the police report lists conflicting driver statements and the at-fault party''s insurance carrier has not yet acknowledged coverage, delaying the subrogation process. The agent is requesting an interim update on fault determination and has noted that the claimant''s signed authorization form for medical records release was lost during transfer between adjusters and needs to be re-executed.', 'agent', 'standard'),
    ('Claimant''s agent submitted a liability claim involving a three-vehicle chain-reaction collision on Interstate 40, but the police report lists conflicting driver statements and the at-fault party''s insurance carrier has not yet acknowledged coverage, leaving subrogation efforts stalled. The agent is requesting an interim update for the insured while awaiting the outstanding police supplement and the third party''s declarations page to confirm active coverage at the time of loss.', 'agent', 'standard'),
    ('Claimant''s agent submitted a liability claim involving a three-vehicle chain-reaction collision on Interstate 40, but the police report lists conflicting driver statements and the at-fault party''s insurance carrier has not yet acknowledged coverage, leaving subrogation efforts stalled. The agent is requesting an interim update for the policyholder while awaiting the missing sworn statements from two of the three involved drivers.', 'agent', 'standard'),
    ('Claimant''s agent submitted a liability claim involving a three-vehicle chain-reaction collision on Interstate 40, but the police report lists conflicting driver statements and the at-fault party''s insurance carrier has not yet acknowledged coverage, leaving subrogation efforts stalled. The agent is requesting an interim update on the status of obtaining the missing sworn statements from the two other involved drivers before the file can proceed to evaluation.', 'agent', 'standard'),
    ('Claimant''s agent submitted a liability claim involving a three-vehicle chain-reaction collision on Interstate 40, but the police report lists conflicting driver statements and the at-fault party''s insurance carrier has not yet acknowledged coverage, leaving the claim pending further documentation and inter-company coordination. The agent has requested an extension to gather the outstanding witness affidavits and medical authorization forms needed to move the evaluation forward.', 'agent', 'standard'),
    ('Client sustained a fractured pelvis and severe soft tissue damage after a marble staircase railing gave way at a luxury resort in Santorini, resulting in a 12-foot fall onto a stone terrace below. Their dedicated account agent filed the claim on their behalf while the client was undergoing surgical intervention at a private hospital in Athens, requesting expedited processing under their platinum personal injury coverage.', 'agent', 'premium'),
    ('During a charity gala at the Ritz-Carlton, our long-standing premium policyholder slipped on a freshly mopped marble floor in the hotel lobby, resulting in a severe rotator cuff tear and fractured wrist requiring surgical intervention. Her personal agent filed the claim on her behalf, noting she has already retained an orthopedic specialist and is seeking coverage for the estimated $87,000 in surgical and rehabilitation costs.', 'agent', 'premium'),
    ('During a guided horseback riding excursion at a luxury resort in Scottsdale, the policyholder was thrown from the horse after it was startled, resulting in a fractured collarbone, two cracked ribs, and significant soft tissue damage requiring surgical intervention. The claim, filed through their dedicated personal risk advisor, includes emergency medical transport, orthopedic surgery costs, a 10-day hospital stay, and six months of projected physical rehabilitation therapy.', 'agent', 'premium'),
    ('During a guided horseback riding excursion at a luxury resort in Scottsdale, the policyholder was thrown from the horse after it was startled, resulting in a fractured collarbone, two cracked ribs, and significant soft tissue damage requiring surgical intervention. The claim, filed through their dedicated personal risk advisor, includes emergency medical transport, orthopedic surgery, a five-day hospital stay, and an estimated twelve-week rehabilitation program at a specialized sports medicine facility.', 'agent', 'premium'),
    ('During a phone call to file his claim, the premium policyholder reported that his recently appraised $85,000 art collection was destroyed in a basement flood, yet the plumber''s inspection report indicates no evidence of water damage to the pipes and the appraisal was obtained just eleven days before the alleged incident. The claimant became evasive when asked for receipts or provenance documentation, stating the original purchase records were conveniently lost in an unrelated move last year.', 'phone', 'premium');
INSERT INTO {database}.{schema}.DEMO_CLAIMS_UNLABELED (CLAIM_SUMMARY, INCIDENT_CHANNEL, CUSTOMER_SEGMENT)
VALUES
    ('During a phone call with his dedicated VIP account manager, the claimant reported that his $85,000 custom wine collection was destroyed when his climate-controlled storage unit allegedly malfunctioned over a holiday weekend, though building maintenance records show no equipment failures and security footage reveals the claimant himself accessed the unit twice during the timeframe in question. The claimant became notably evasive when asked about a recent listing on a luxury auction site matching several of the supposedly ruined vintages.', 'phone', 'vip'),
    ('During a phone call with his dedicated account representative, long-standing platinum policyholder and prominent real estate developer Mr. Harrison Caldwell reported sustaining a severe rotator cuff tear and fractured collarbone after falling from a raised VIP platform at a charity gala event on Saturday evening. Mr. Caldwell indicated he was transported by ambulance to Cedar-Sinai Medical Center, where surgeons have recommended immediate arthroscopic repair surgery followed by an estimated four-month rehabilitation period.', 'phone', 'vip'),
    ('During a phone call with his dedicated account representative, long-standing platinum policyholder and prominent real estate developer Mr. Harrison Caldwell reported sustaining a severe rotator cuff tear and fractured collarbone after falling from a raised VIP platform at a charity gala event on Saturday evening. Mr. Caldwell indicated he was transported by ambulance to Cedar-Sinai Medical Center, where surgeons have recommended immediate arthroscopic surgery followed by an extended rehabilitation program expected to last several months.', 'phone', 'vip'),
    ('During a phone call with his dedicated account representative, long-standing platinum policyholder and prominent real estate developer Mr. Harrison Caldwell reported sustaining a severe rotator cuff tear and fractured collarbone after falling from a raised VIP seating platform that collapsed at a charity gala event on Saturday evening. Mr. Caldwell indicated he was transported by ambulance to Cedar-Sinai Medical Center, where surgeons have recommended immediate arthroscopic repair surgery followed by an extended rehabilitation program expected to last several months.', 'phone', 'vip'),
    ('During a phone call with our premium services team, the policyholder reported sustaining a severe rotator cuff tear and multiple rib fractures after being struck by a falling display shelf at a home improvement store, requiring emergency surgery and an extended rehabilitation program estimated at fourteen weeks.', 'phone', 'premium'),
    ('During a phone call with our priority claims team, a long-standing VIP policyholder reported that his vacation home in Aspen was burglarized over the weekend, with thieves taking a collection of rare first-edition books valued at approximately $185,000, a custom-built home theater system, and several pieces of designer furniture. The client noted that the alarm system had been professionally disabled and requested expedited processing given his upcoming international travel schedule.', 'phone', 'vip'),
    ('During a phone call with our priority claims team, a long-standing VIP policyholder reported that his vacation home in Aspen was burglarized over the weekend, with thieves taking a collection of rare first-edition books valued at approximately $185,000, a custom-built home theater system, and several pieces of designer furniture. The client noted that the alarm system had been professionally disabled and requested expedited processing given his upcoming international travel schedule.', 'phone', 'vip'),
    ('During a phone call with our priority claims team, a long-standing VIP policyholder reported that his vacation home in Aspen was burglarized over the weekend, with thieves taking a collection of rare first-edition books valued at approximately $185,000, a custom-built home theater system, and several pieces of designer furniture. The client noted that the alarm system had been professionally disabled and requested expedited processing given his upcoming international travel schedule.', 'phone', 'vip'),
    ('During a phone call with our priority claims team, a long-standing VIP policyholder reported that his vacation home in Aspen was burglarized over the weekend, with thieves taking a collection of rare first-edition books valued at approximately $185,000, a custom-built home theater system, and several pieces of designer furniture. The client noted that the alarm system had been professionally disabled and requested expedited processing given his upcoming international travel schedule.', 'phone', 'vip'),
    ('During a phone call with our priority claims team, a long-standing VIP policyholder reported that his vacation home in Aspen was burglarized over the weekend, with thieves taking a curated collection of vintage watches valued at approximately $185,000, two original oil paintings, and a custom-built home theater system. The client noted that the alarm system had been professionally disabled and requested expedited processing given his upcoming international travel schedule.', 'phone', 'vip'),
    ('During a phone call with our priority claims team, a long-standing VIP policyholder reported that his vacation home in Aspen was burglarized over the weekend, with thieves taking a curated collection of vintage watches valued at approximately $340,000, two original oil paintings, and a wall-mounted safe containing rare gold coins. The local sheriff''s department has opened an investigation, and the client has provided detailed appraisals and photographic documentation for all stolen items.', 'phone', 'vip'),
    ('During a phone call with our priority claims team, a long-standing premium policyholder reported sustaining a severe rotator cuff tear and multiple rib fractures after a ceiling-mounted light fixture collapsed onto her at an upscale restaurant during a private dinner event. She has already been evaluated by an orthopedic surgeon who is recommending arthroscopic surgery, and she is requesting expedited processing given her upcoming international travel commitments.', 'phone', 'premium'),
    ('During a phone call with our priority claims team, a long-standing premium policyholder reported sustaining a severe rotator cuff tear and multiple rib fractures after being struck by a falling display shelf at a home improvement store, requiring emergency surgery and an estimated eight-week recovery period. The claimant has retained legal counsel and is seeking coverage for surgical costs, physical rehabilitation, and loss of income from his consulting practice during the recovery window.', 'phone', 'premium'),
    ('During a phone call with our priority claims team, a long-standing premium policyholder reported sustaining a severe rotator cuff tear and multiple rib fractures after being struck by a falling display shelf at a home improvement store, requiring emergency surgery and an extended rehabilitation program. The claimant, who holds our Platinum coverage tier, indicated he has already retained legal counsel and is seeking full medical expense reimbursement along with compensation for lost executive-level income during his projected four-month recovery period.', 'phone', 'premium'),
    ('During a phone call with our priority claims team, a long-standing premium policyholder reported sustaining a severe rotator cuff tear and multiple rib fractures after being struck by a falling display shelf at a home improvement store, requiring emergency surgery and an extended rehabilitation program. The claimant, who holds our comprehensive personal injury rider, indicated that the store''s management acknowledged the shelving unit had been flagged for repair weeks prior to the incident.', 'phone', 'premium'),
    ('During a phone call with our priority claims team, a long-standing premium policyholder reported sustaining a severe rotator cuff tear and multiple rib fractures after being struck by a falling display shelf at a home improvement store, requiring emergency surgery and an extended rehabilitation program. The claimant, who holds our comprehensive personal injury rider, indicated they have retained legal counsel and are seeking coverage for surgical costs, physical therapy, lost executive-level income, and ongoing pain management.', 'phone', 'premium'),
    ('During a phone call with our priority claims team, a long-standing premium policyholder reported that his 2023 Mercedes-Benz GLE was rear-ended at a red light by a distracted driver, resulting in significant bumper and trunk damage along with deployment of rear sensors, and he is requesting expedited processing for both vehicle repairs at his preferred dealership and a luxury loaner vehicle while his SUV is in the shop.', 'phone', 'premium'),
    ('During a phone call with our priority claims team, a longtime premium policyholder reported that his 2023 Mercedes-Benz GLE was rear-ended at a red light by a distracted driver, resulting in significant bumper and trunk damage, deployment of rear sensors, and persistent warning lights on the dashboard. The member requested expedited processing and a luxury loaner vehicle while repairs are completed at his preferred certified body shop.', 'phone', 'premium'),
    ('During a phone call with our priority claims team, a longtime premium policyholder reported that his 2023 Mercedes-Benz GLE was rear-ended at a red light by a distracted driver, resulting in significant bumper, trunk, and taillight damage along with deployment of rear sensors, and he is requesting expedited processing for both vehicle repairs and a luxury-class rental vehicle while his car is in the shop. The claimant noted persistent neck stiffness following the impact and indicated he would be seeking evaluation from his physician.', 'phone', 'premium'),
    ('During a phone call with our priority claims team, a longtime premium policyholder reported that his 2023 Mercedes-Benz GLE was rear-ended at a stoplight by a distracted driver, resulting in significant bumper and trunk damage along with deployment of rear sensors, and he is requesting expedited processing for both vehicle repairs and a luxury-class rental replacement.', 'phone', 'premium'),
    ('During a phone call with our priority claims team, a longtime premium policyholder reported that his 2023 Mercedes-Benz GLE was rear-ended at a stoplight by a distracted driver, resulting in significant bumper and trunk damage, deployment of rear sensors, and persistent warning lights on the dashboard. The member requested expedited processing and a luxury loaner vehicle while repairs are completed at his preferred certified body shop.', 'phone', 'premium'),
    ('During a phone consultation, our VIP client, a prominent real estate developer, reported sustaining a severe rotator cuff tear and multiple rib fractures after a scaffolding collapse at one of his commercial property sites during a personal walkthrough inspection. He is currently awaiting surgical consultation and has requested expedited processing given upcoming international business commitments that may need to be postponed.', 'phone', 'vip'),
    ('During a phone consultation, our VIP client, a prominent real estate developer, reported sustaining a severe rotator cuff tear and multiple rib fractures after a scaffolding collapse at one of his commercial property sites under renovation. He has already undergone emergency surgery and is requesting expedited processing of his personal injury claim to cover projected rehabilitation costs and loss of income during his extended recovery period.', 'phone', 'vip'),
    ('During a phone consultation, our VIP client, a prominent real estate developer, reported sustaining a severe rotator cuff tear and multiple rib fractures after a scaffolding collapse at one of his commercial property sites, requiring immediate surgical intervention and an estimated eight-month rehabilitation period. He is seeking expedited processing of his personal injury claim, including coverage for surgical costs, physical therapy, and loss of income during recovery.', 'phone', 'vip'),
    ('During a phone consultation, our platinum-tier client, a prominent real estate developer, reported that critical subcontractor liability waivers and third-party indemnification agreements for a $14.2 million commercial project were lost during a transition between two brokerage firms, leaving multiple parties potentially exposed on an active construction defect claim involving the general contractor, three subcontractors, and the property management company. The client has requested expedited reconstruction of the coverage documentation and immediate assignment of a senior claims specialist to coordinate between all five involved insurers before the upcoming mediation deadline.', 'phone', 'vip'),
    ('During a phone consultation, our platinum-tier client, a prominent real estate developer, reported that critical subcontractor liability waivers and third-party indemnification agreements for a $14.2 million commercial project were lost during a transition between two brokerage firms, leaving multiple parties potentially exposed. The client is requesting expedited reconstruction of all missing documentation and interim coverage confirmation while liability boundaries between the general contractor, three subcontractors, and the property owner are formally re-established.', 'phone', 'vip'),
    ('During a severe hailstorm on March 14th, our lakefront property sustained extensive damage including shattered skylights in the master suite and great room, deep pitting across the cedar shake roof requiring full replacement, and destruction of the custom outdoor kitchen and pergola. We have uploaded contractor assessments, drone footage of the roof damage, and receipts for the emergency tarping service through the claims portal for your review.', 'web', 'premium'),
    ('During a severe hailstorm on March 14th, our lakefront property sustained extensive damage including shattered skylights in the master suite, deep pitting across the cedar shake roof requiring full replacement, and destruction of the custom-built outdoor kitchen and pergola. We have uploaded contractor estimates, drone footage of the roof damage, and our home inventory documentation through the online claims portal for your review.', 'web', 'premium'),
    ('During a severe hailstorm on March 14th, our premium policyholder called to report extensive damage to their 4,200 sq ft estate, including shattered skylights in the master suite and sunroom, punctured copper roofing across the main structure and detached guest house, and hail-pocked limestone exterior cladding requiring specialist restoration. The homeowner also noted significant water intrusion through the compromised skylights, affecting custom Italian plaster ceilings and hardwood flooring on the upper level.', 'phone', 'premium'),
    ('During a severe hailstorm on March 14th, our premium policyholder called to report extensive damage to their 4,200 sq ft estate, including shattered skylights in the master suite and sunroom, punctured copper roofing, and water intrusion that warped imported hardwood flooring throughout the second level. The homeowner also noted that their outdoor kitchen, pool enclosure, and landscaped courtyard sustained significant structural and cosmetic damage from golf ball-sized hail.', 'phone', 'premium'),
    ('During a severe hailstorm on March 9th, our cedar shake roof sustained extensive damage with multiple areas of cracked and missing shingles, and two skylights were shattered, allowing water to pour into our master bedroom and home office, ruining custom built-in cabinetry and hardwood flooring. The policyholder called in visibly upset, requesting expedited service given their premium status, and mentioned they have already engaged a licensed roofing contractor to tarp the exposed areas to prevent further interior damage.', 'phone', 'premium'),
    ('During a severe hailstorm on the evening of June 3rd, our estate in Scottsdale sustained extensive damage to the clay tile roof, three skylights were shattered, and significant water intrusion affected the master suite, home theater, and wine cellar, resulting in damage to rare collectibles and custom finishes. I contacted my dedicated advisor immediately and need expedited assessment given upcoming international travel commitments later this week.', 'phone', 'vip'),
    ('During a severe hailstorm on the evening of March 14th, our estate in Scottsdale sustained extensive damage to the clay tile roof, three skylights were shattered, and significant water intrusion occurred in the master suite and wine cellar, affecting several rare collections. I''m calling to initiate a claim immediately as we''ve already had our private contractor assess the damage and can provide a preliminary repair estimate of approximately $187,000.', 'phone', 'vip'),
    ('During a severe hailstorm with winds exceeding 70 mph, our client''s custom-built lakefront estate sustained extensive damage including shattered skylights, compromised cedar shake roofing across all three structures, and significant water intrusion into the finished basement housing a climate-controlled wine cellar and home theater. The client''s dedicated agent filed the claim immediately and has arranged for emergency tarping services while coordinating with the preferred contractor network for a comprehensive damage assessment.', 'agent', 'premium'),
    ('During a severe hailstorm with winds exceeding 70 mph, our client''s custom-built lakefront estate sustained extensive damage including shattered skylights, compromised cedar shake roofing across all three structures, and significant water intrusion into the finished basement housing a climate-controlled wine cellar and home theater. The client''s dedicated agent filed the claim immediately and has arranged for emergency tarping services while coordinating with the preferred contractor network for a comprehensive damage assessment.', 'agent', 'premium'),
    ('During a severe thunderstorm on March 14th, a large oak tree in our backyard was uprooted and crashed through the roof of our attached garage, causing extensive structural damage to the roof trusses, drywall, and crushing our stored belongings inside. We have temporarily tarped the opening to prevent further water intrusion and are requesting an adjuster visit at the earliest convenience.', 'web', 'standard'),
    ('During a severe thunderstorm on March 14th, a large oak tree in our backyard was uprooted and crashed through the roof of our detached garage, collapsing a significant portion of the structure and damaging the vehicle parked inside. I am filing this claim through the online portal to request coverage for the garage roof repair, structural rebuilding, and assessment of damage to our 2019 Honda CR-V.', 'web', 'standard'),
    ('During a severe thunderstorm on March 14th, a large oak tree in the backyard was uprooted and crashed through the roof of the insured''s two-story colonial home, causing extensive damage to the master bedroom and allowing significant water intrusion throughout the second floor. The homeowner contacted their insurance agent the following morning to file the claim, noting that temporary tarping had been arranged but mold concerns were already emerging due to saturated drywall and insulation.', 'agent', 'standard'),
    ('During a severe thunderstorm on the evening of March 12th, a large oak tree in the backyard was uprooted by high winds and crashed through the roof of the two-story colonial home, causing extensive damage to the master bedroom and allowing significant rainwater intrusion into the second floor and ceiling below. The homeowner called to file the claim the following morning after tarping the roof overnight, reporting that drywall, flooring, and personal belongings in both affected rooms were heavily damaged.', 'phone', 'standard'),
    ('During a severe thunderstorm on the evening of March 12th, a large oak tree in the backyard was uprooted by high winds and crashed through the roof of the two-story colonial home, causing extensive damage to the master bedroom, attic insulation, and allowing significant rainwater intrusion into the second floor. The homeowner called in the claim the following morning after emergency tarping was placed by a local contractor to prevent further water damage.', 'phone', 'standard'),
    ('During a severe thunderstorm on the evening of March 12th, a large oak tree in the backyard was uprooted by high winds and crashed through the roof of the two-story colonial home, causing extensive damage to the master bedroom, attic insulation, and allowing significant rainwater intrusion into the second floor. The homeowner called to file the claim the following morning after tarping the roof overnight and reported that the ceiling drywall had collapsed in two rooms and the hardwood flooring was beginning to warp from water saturation.', 'phone', 'standard'),
    ('During a severe thunderstorm on the evening of March 12th, a large oak tree was uprooted and crashed through the roof of our lakefront estate''s master suite and adjoining sunroom, causing extensive structural damage and allowing significant water intrusion that ruined custom millwork, imported Italian marble flooring, and a curated art collection valued at over $280,000. I''m calling because we need an expedited response given the ongoing exposure to the elements and the upcoming charity gala we''re scheduled to host at the property next month.', 'phone', 'vip'),
    ('During a severe thunderstorm on the evening of March 12th, a large oak tree was uprooted and crashed through the roof of our lakefront estate, causing extensive structural damage to the master suite and flooding the second floor due to prolonged rain exposure before emergency tarping could be arranged. I''m requesting expedited handling given the home is currently uninhabitable and we need immediate coordination with our preferred restoration contractor.', 'phone', 'vip'),
    ('During a severe thunderstorm on the evening of March 14th, a large oak tree in the backyard was uprooted by high winds and crashed through the roof of the two-story colonial home, causing extensive damage to the master bedroom and allowing significant rainwater intrusion into the second floor and ceiling below. The homeowner called to file the claim the following morning after tarping the roof overnight, reporting that drywall, carpeting, and several pieces of furniture were destroyed by the water damage.', 'phone', 'standard'),
    ('During a severe thunderstorm on the evening of March 9th, a large oak tree in the backyard was uprooted by high winds and crashed through the roof of the two-story colonial home, causing extensive damage to the master bedroom and allowing significant rainwater intrusion into the second floor and ceiling below. The homeowner called to file the claim the following morning after tarping the roof overnight, noting that drywall, carpet, and several pieces of furniture were damaged beyond repair.', 'phone', 'standard'),
    ('During a weekend getaway, our client returned to their gated community residence to discover that sophisticated thieves had bypassed the alarm system and stolen a curated art collection valued at $187,000, along with a home safe containing rare coins and luxury watches. The client''s dedicated agent has expedited the claim filing and arranged for an independent art appraiser to assist with the valuation process.', 'agent', 'premium'),
    ('During a weekend getaway, our home security system was disabled and intruders gained entry through a rear sliding door, stealing my wife''s jewelry collection valued at approximately $47,000, a set of rare first-edition books, and two luxury watches from our bedroom safe. I''ve attached the police report, security camera footage from our neighbor''s property capturing the suspects'' vehicle, and certified appraisals for all missing items for your immediate review.', 'email', 'premium'),
    ('During a weekend getaway, our home was targeted by burglars who bypassed the alarm system and stole my wife''s jewelry collection valued at approximately $87,000, including a vintage Cartier bracelet and several heirloom pieces, along with a wall safe containing $15,000 in cash and important documents. I''m calling to file this claim immediately as the police report has already been submitted and our private security company is reviewing surveillance footage from neighboring properties.', 'phone', 'premium'),
    ('During a weekend getaway, our home was targeted by burglars who bypassed the alarm system and stole my wife''s jewelry collection valued at approximately $87,000, including a vintage Cartier bracelet and several heirloom pieces, along with a wall safe containing $15,000 in cash and important documents. I''m calling to file this claim immediately as the police report has already been submitted and our private security company is reviewing surveillance footage from neighboring properties.', 'phone', 'premium'),
    ('During a weekend getaway, our home was targeted by burglars who bypassed the alarm system and stole my wife''s jewelry collection valued at approximately $87,000, including several heirloom pieces, along with two luxury watches and a wall safe containing $15,000 in cash. I''m calling to file this claim immediately and would appreciate having a dedicated adjuster assigned given the significant value involved and the need to coordinate with the ongoing police investigation.', 'phone', 'premium');
INSERT INTO {database}.{schema}.DEMO_CLAIMS_UNLABELED (CLAIM_SUMMARY, INCIDENT_CHANNEL, CUSTOMER_SEGMENT)
VALUES
    ('During a weekend getaway, our home was targeted by burglars who bypassed the alarm system and stole my wife''s jewelry collection valued at approximately $87,000, including several heirloom pieces, along with two luxury watches and a wall safe containing $15,000 in cash. I''m calling to file this claim immediately as the police report has already been submitted and our security company is providing footage from the exterior cameras.', 'phone', 'premium'),
    ('During a weekend getaway, our home was targeted by burglars who bypassed the alarm system and stole my wife''s jewelry collection valued at approximately $87,000, including several heirloom pieces, along with two luxury watches and a wall safe containing $15,000 in cash. I''m calling to file this claim immediately as the police report has been filed and our security company is providing footage from the exterior cameras to assist with the investigation.', 'phone', 'premium'),
    ('During a weekend getaway, our lakefront vacation home in Lake Geneva was broken into and thieves removed approximately $47,000 worth of fine art, a vintage Rolex Submariner, and a custom-built home theater system, with the security camera footage showing two masked individuals entering through a forced rear sliding door. The local police report has been filed and our property manager discovered the break-in Monday morning when arriving for scheduled maintenance.', 'web', 'premium'),
    ('During a weekend getaway, our premium policyholder''s residence was targeted by burglars who bypassed the alarm system and stole a curated art collection valued at $187,000, along with a home safe containing rare coins and important financial documents. The claim was filed through their dedicated agent on Monday morning after the homeowner returned to discover the forced entry through a rear basement window.', 'agent', 'premium'),
    ('During a weekend getaway, the claimant''s residence was targeted by burglars who bypassed the alarm system and removed a curated art collection valued at $187,000, along with a home safe containing rare coins and luxury watches. The claimant contacted us by phone upon returning home Sunday evening after discovering the forced entry through a rear sliding door and has already filed a police report and provided the security camera footage from neighboring properties.', 'phone', 'premium'),
    ('During a weekend getaway, the insured''s residence was targeted by burglars who bypassed the alarm system and removed a curated art collection valued at $187,000, along with a home safe containing rare coins and important financial documents. The insured''s dedicated agent filed the claim immediately upon notification, coordinating with both the private security company and local detectives to expedite the investigation and recovery efforts.', 'agent', 'premium'),
    ('During an overseas business trip, our home security system was disabled and intruders gained entry through a rear patio door, stealing my wife''s jewelry collection valued at approximately $87,000, a set of rare first-edition books, and two luxury watches from our bedroom safe, which was pried open. We are submitting this claim along with the police report, security camera footage from neighboring properties, and certified appraisals for all items taken.', 'email', 'premium'),
    ('During last Thursday''s severe thunderstorm, a large oak tree in our backyard was uprooted and crashed through the roof of our detached garage, collapsing a significant portion of the structure and damaging the vehicle parked inside. I''ve attached photos of the damage along with an estimate from a local contractor for emergency tarping and structural assessment, and I''d appreciate guidance on next steps for filing this claim.', 'email', 'standard'),
    ('During last Thursday''s severe thunderstorm, a large oak tree in our backyard was uprooted and crashed through the roof of our detached garage, collapsing a significant portion of the structure and damaging the vehicle parked inside. I''ve attached photos of the damage along with an estimate from a local contractor, and I''d appreciate guidance on next steps for filing this claim.', 'email', 'standard'),
    ('During last Thursday''s severe thunderstorm, a large oak tree in our backyard was uprooted by high winds and crashed through the roof of our attached garage, causing significant structural damage to the roof trusses and crushing my wife''s vehicle parked inside. I''ve attached photos of the damage and a preliminary estimate from a local contractor; please advise on next steps for getting an adjuster out to assess the full extent of the loss.', 'email', 'standard'),
    ('During last Thursday''s severe thunderstorm, a large oak tree in our backyard was uprooted by high winds and crashed through the roof of our attached garage, causing significant structural damage to the roof trusses and crushing my wife''s vehicle parked inside. I''ve attached photos of the damage and a preliminary estimate from a local contractor; please advise on next steps for getting an adjuster out to assess the full extent of the loss.', 'email', 'standard'),
    ('During last night''s severe thunderstorm, a large oak tree on my estate was uprooted and crashed through the roof of my primary residence''s west wing, causing extensive structural damage to the master suite and flooding from rain pouring through the opening. I''m currently staying at the Four Seasons and need an adjuster dispatched immediately, as my personal assistant can provide access to the property at any time.', 'phone', 'vip'),
    ('During last night''s severe thunderstorm, a large oak tree on my estate was uprooted and crashed through the roof of my primary residence''s west wing, causing extensive structural damage to the master suite, home office, and the adjacent wine cellar where I store a curated collection valued at over $180,000. I''m calling from my secondary home in Aspen and need an adjuster dispatched immediately, as my property manager reports significant water intrusion through the compromised roof.', 'phone', 'vip'),
    ('During last night''s severe thunderstorm, a large oak tree on our property was uprooted and crashed through the roof of our four-car detached garage, collapsing a significant portion of the structure and damaging two vehicles stored inside, including a classic 1967 Mustang. The policyholder called in visibly shaken, requesting immediate dispatch of an adjuster and temporary tarping services to prevent further water intrusion from the forecasted rain later this week.', 'phone', 'premium'),
    ('During last night''s severe thunderstorm, a large oak tree on our property was uprooted and crashed through the roof of our four-car detached garage, collapsing a significant portion of the structure and damaging two vehicles stored inside, including a classic 1967 Mustang. The policyholder called in visibly shaken, requesting immediate dispatch of an adjuster and temporary tarping services to prevent further water intrusion from the ongoing rain.', 'phone', 'premium'),
    ('During last night''s severe thunderstorm, a large oak tree on our property was uprooted and crashed through the roof of our four-car detached garage, collapsing a significant portion of the structure and damaging two vehicles stored inside. I''m calling to file a claim immediately as we''ve already had our contractor tarp the exposed area, and I''d like to coordinate the adjuster visit with our personal account representative.', 'phone', 'premium'),
    ('During the severe thunderstorm on March 12th, a large oak tree in our backyard was uprooted and crashed through the roof of our attached garage, causing extensive structural damage and destroying one of our vehicles parked inside. We submitted photos and a preliminary contractor estimate of $47,000 for roof and garage repairs through the online claims portal.', 'web', 'standard'),
    ('During the severe thunderstorm on March 14th, a large oak tree in our backyard was uprooted and crashed through the roof of our attached garage, causing extensive structural damage and destroying one of our vehicles parked inside. I''ve attached photos of the damage and the emergency tarp installation receipt from the contractor who came out that evening to prevent further water intrusion.', 'email', 'standard'),
    ('During the severe thunderstorm on March 14th, a large oak tree in our backyard was uprooted and crashed through the roof of our attached garage, causing extensive structural damage and destroying one of our vehicles parked inside. I''ve attached photos of the damage and the emergency tarp installation receipt from the contractor who came out that evening to prevent further water intrusion.', 'email', 'standard'),
    ('During the severe thunderstorm on March 14th, a large oak tree in our backyard was uprooted and crashed through the roof of our attached garage, causing extensive structural damage and destroying one of our vehicles parked inside. We submitted photos and a preliminary estimate from our contractor through the online portal and are requesting coverage for both the roof repair and interior water damage that resulted from the overnight exposure.', 'web', 'standard'),
    ('During the severe thunderstorm on March 14th, a large oak tree in our backyard was uprooted and crashed through the roof of our attached garage, causing extensive structural damage and destroying one of our vehicles parked inside. We submitted photos and a preliminary estimate from our contractor through the online portal and are requesting coverage for both the roof repair and the damaged personal property stored in the garage.', 'web', 'standard'),
    ('During the severe thunderstorm on March 14th, a large oak tree in our backyard was uprooted and crashed through the roof of our attached garage, causing extensive structural damage to the roof trusses, drywall, and crushing our storage shelving. We''ve placed tarps over the opening to prevent further water intrusion and are requesting an adjuster visit as soon as possible.', 'web', 'standard'),
    ('First-time policyholder Marcus Delaney contacted his agent three days after a deer ran into the driver''s side of his 2021 Hyundai Tucson on a rural highway at dusk, causing significant damage to the front quarter panel, side mirror, and door. The agent filed the comprehensive claim on Mr. Delaney''s behalf, noting that the vehicle was still drivable but the door no longer seals properly, allowing water intrusion during rain.', 'agent', 'new_customer'),
    ('First-time policyholder Marcus Delaney contacted his agent three days after a deer ran into the driver''s side of his 2022 Hyundai Tucson on a rural highway at dusk, causing significant damage to the front quarter panel, side mirror, and door. The agent filed the comprehensive claim on Mr. Delaney''s behalf, noting that the vehicle was still drivable but the door no longer seals properly, allowing water intrusion during rain.', 'agent', 'new_customer'),
    ('First-time policyholder Marcus Delaney contacted his insurance agent after his 2023 Kia Sportage was rear-ended at a red light on Route 9 by a distracted driver, resulting in a crushed rear bumper, damaged tailgate, and misaligned rear axle. The agent filed the claim on Mr. Delaney''s behalf, noting that a police report was obtained at the scene and the other driver''s insurance information was collected.', 'agent', 'new_customer'),
    ('First-time policyholder called in through their assigned agent to report that their 2023 Kia Sportage was rear-ended at a red light on Route 9 by a distracted driver, resulting in significant bumper and tailgate damage along with a malfunctioning backup camera. The customer, who purchased their policy just eleven days ago, confirmed a police report was filed and that the other driver''s insurance information was obtained at the scene.', 'agent', 'new_customer'),
    ('First-time policyholder called to report that her 2023 Kia Sportage was rear-ended at a red light on Route 9 by a distracted driver, resulting in significant bumper and trunk damage along with a malfunctioning backup camera. She mentioned experiencing neck stiffness since the accident two days ago and requested guidance on both the vehicle repair process and any medical coverage under her new policy.', 'phone', 'new_customer'),
    ('First-time policyholder called to report that her 2023 Kia Sportage was rear-ended at a red light on Route 9 this morning by a distracted driver, resulting in significant bumper and tailgate damage along with a malfunctioning backup camera. She mentioned she just activated her policy eleven days ago and is unsure how the claims process works, requesting guidance on next steps and rental car coverage.', 'phone', 'new_customer'),
    ('First-time policyholder called to report that her 2023 Kia Sportage was rear-ended at a red light on Route 9 this morning by a distracted driver, resulting in significant bumper and tailgate damage along with a malfunctioning backup camera. She mentioned she just purchased the policy three weeks ago and is unsure how the claims process works, requesting guidance on next steps and rental car coverage.', 'phone', 'new_customer'),
    ('First-time policyholder called to report that her 2023 Kia Sportage was rear-ended at a red light on Route 9 this morning by a distracted driver, resulting in significant bumper and tailgate damage along with a malfunctioning rear camera. She mentioned she just purchased the policy three weeks ago and was unsure how to proceed with getting repair estimates.', 'phone', 'new_customer'),
    ('First-time policyholder reported through their assigned agent that a delivery truck sideswiped their parked 2021 Honda Accord in a grocery store parking lot, shearing off the driver-side mirror and leaving deep scratches along the entire left panel. The customer, who activated their policy just eleven days ago, provided dashcam footage from a nearby store security camera obtained with management''s assistance.', 'agent', 'new_customer'),
    ('I just purchased my vehicle three weeks ago and was rear-ended at a red light on Route 9 yesterday evening by a distracted driver, resulting in a crushed rear bumper, broken taillights, and a misaligned trunk that won''t close properly. I submitted this claim through your website along with the police report number and photos taken at the scene.', 'web', 'new_customer'),
    ('I just purchased my vehicle three weeks ago and was rear-ended at a red light on Route 9 yesterday evening by a distracted driver, resulting in significant damage to my rear bumper, trunk, and taillights. I submitted this claim through your website along with the police report number and photos from the scene.', 'web', 'new_customer'),
    ('I just purchased my vehicle three weeks ago and was rear-ended at a stoplight on Route 9 yesterday evening by a distracted driver, resulting in a crushed rear bumper, broken taillights, and a misaligned trunk that won''t close properly. I submitted this claim through your website along with the police report number and photos taken at the scene.', 'web', 'new_customer'),
    ('I just purchased my vehicle three weeks ago and was rear-ended at a stoplight on Route 9 yesterday evening by a distracted driver, resulting in significant damage to my rear bumper, trunk, and taillights. I submitted this claim through your website along with the police report number and photos from the scene.', 'web', 'new_customer'),
    ('I just purchased my vehicle three weeks ago and was rear-ended at a stoplight on Route 9 yesterday evening by a distracted driver, resulting in significant damage to my rear bumper, trunk, and taillights. I submitted this claim through your website along with the police report number and photos from the scene.', 'web', 'new_customer'),
    ('I just signed up for my policy three weeks ago and already need to file a claim—someone ran a red light at the intersection of Oak Street and Highway 9 yesterday evening and T-boned my 2023 Hyundai Tucson on the driver''s side, causing extensive door and frame damage. I submitted photos through the online portal showing the impact area and the other driver''s insurance information.', 'web', 'new_customer'),
    ('I recently purchased my 2024 Kia Sportage three weeks ago and am filing my first claim after a delivery truck sideswiped my vehicle while it was parked outside my apartment complex, leaving deep scratches and dents along the entire passenger side. I have security camera footage from the building and the truck driver''s information, and I submitted photos of the damage to the email address provided during my policy setup.', 'email', 'new_customer'),
    ('I recently purchased my 2024 Kia Sportage three weeks ago and am filing my first claim after a distracted driver ran a stop sign and T-boned me at an intersection on Route 9, causing extensive damage to the passenger side doors and deploying the side curtain airbags. I''ve attached photos from the scene along with a copy of the police report and the other driver''s insurance information to this email.', 'email', 'new_customer'),
    ('I recently purchased my 2024 Kia Sportage three weeks ago and yesterday evening a deer ran into the driver''s side while I was traveling on Route 9 near Poughkeepsie, causing significant damage to the front left fender, door panel, and side mirror. I''m submitting photos of the damage via this email and would appreciate guidance on next steps since this is my first time filing a claim with your company.', 'email', 'new_customer'),
    ('I was visiting a friend''s apartment complex for the first time when I slipped on an unmarked wet floor in the lobby, landing hard on my back and hitting my head on the tile. I went to the emergency room where they diagnosed me with a mild concussion and two herniated discs, and I''m submitting this claim via email as I just activated my policy three weeks ago.', 'email', 'new_customer'),
    ('I was visiting a friend''s apartment complex for the first time when a loose metal railing on the exterior staircase gave way, causing me to fall approximately eight feet onto the concrete below and fracture my left wrist and two ribs. I submitted this claim via email along with the emergency room discharge papers and photographs of the defective railing taken by a bystander who witnessed the fall.', 'email', 'new_customer'),
    ('I was walking through the parking lot of a grocery store on Elm Street last Tuesday when a shopping cart corral that was improperly secured broke free and struck me in the lower back, causing severe muscle spasms and bruising that required an emergency room visit. I just purchased my policy three weeks ago and am submitting this claim via email along with the ER discharge papers and photos of the damaged cart corral.', 'email', 'new_customer'),
    ('I was walking through the parking lot of a grocery store on Elm Street last Tuesday when a shopping cart corral that was improperly secured broke free and struck me in the lower back, causing severe muscle spasms and bruising that required an emergency room visit. I just purchased my policy three weeks ago and am submitting this claim via email along with the ER discharge papers and photos of the damaged cart corral.', 'email', 'new_customer'),
    ('Long-standing platinum policyholder called to report a $187,000 jewelry theft from his home safe while vacationing in Monaco, but security camera footage shows no signs of forced entry and the alarm system was manually disarmed using the correct code during the alleged timeframe of the burglary. The claimant became evasive when asked about recent financial difficulties and initially provided conflicting dates for when he last verified the items were in the safe.', 'phone', 'vip'),
    ('Long-standing platinum policyholder called to report a $187,000 jewelry theft from his home safe while vacationing in Monaco, but the alarm system logs show it was manually disarmed using the correct code during the alleged break-in, and the claimant''s ex-business partner was recently named in a civil lawsuit filed by the insured. The claimant became notably evasive when the intake specialist asked about recent appraisals and whether a police report had been filed, stating he "wanted to handle things quietly through insurance first."', 'phone', 'vip'),
    ('Long-standing platinum policyholder called to report a $187,000 jewelry theft from his home safe while vacationing in Monaco, but the alarm system logs show it was manually disarmed using the correct code during the alleged break-in, and the claimant''s ex-business partner was recently named in a civil lawsuit filed by the insured. The claimant became notably evasive when the intake specialist asked about the last time the safe combination was changed and requested expedited payment due to an upcoming real estate closing.', 'phone', 'vip'),
    ('Long-standing platinum policyholder called to report a $187,000 jewelry theft from his home safe while vacationing in Monaco, but the alarm system logs show no breach and the claimant''s ex-business partner, currently involved in a civil lawsuit against him, was listed as the only other person with the safe combination. The claimant became evasive when asked about recent financial difficulties and insisted on an expedited payout, citing his VIP status and 22-year relationship with the company.', 'phone', 'vip'),
    ('Long-standing platinum policyholder submitted a web claim for $187,000 in water damage to their vacation home in Aspen, but the submitted photos contain metadata showing they were taken three weeks before the alleged pipe burst date, and a neighbor reports the property has been listed for sale in its current condition since last month.', 'web', 'vip'),
    ('New customer called to file a claim involving a three-vehicle chain-reaction collision on I-95, but is unable to locate the police report number or the contact information for the other two drivers'' insurance carriers, complicating liability determination across multiple parties. The customer stated the accident occurred eleven days ago and that the responding officer provided a card at the scene which has since been misplaced during a recent move.', 'phone', 'new_customer');
INSERT INTO {database}.{schema}.DEMO_CLAIMS_UNLABELED (CLAIM_SUMMARY, INCIDENT_CHANNEL, CUSTOMER_SEGMENT)
VALUES
    ('New customer called to file a claim involving a three-vehicle chain-reaction collision on I-95, but is unable to locate the police report number or the other two drivers'' insurance information, as the responding officer provided a handwritten incident reference that has since become illegible. The customer reports that one of the other vehicles was a commercial delivery truck, adding a potential third-party commercial carrier to the claim that has yet to be identified or contacted.', 'phone', 'new_customer'),
    ('New customer called to file a claim involving a three-vehicle chain-reaction collision on I-95, but is unable to locate the police report number or the other two drivers'' insurance information, as the responding officer provided a handwritten incident reference that has since become illegible. The customer reports that one of the other vehicles was a commercial delivery truck, adding a potential third-party commercial carrier to the claim that has yet to be identified or contacted.', 'phone', 'new_customer'),
    ('New customer called to file a claim involving a three-vehicle chain-reaction collision on I-95, but is unable to locate the police report or the other two drivers'' insurance information, and one of the vehicles involved was a commercial delivery truck operating under a different fleet insurance policy. The customer stated the responding officer provided a case number verbally but never issued a written report at the scene, complicating efforts to establish fault among the three parties.', 'phone', 'new_customer'),
    ('New customer called to file a claim involving a three-vehicle chain-reaction collision on I-95, but is unable to provide the police report or the other two drivers'' insurance information, as the responding officer only gave a verbal case number that doesn''t appear in the county records system. The customer states he was rear-ended first and pushed into the vehicle ahead, and is requesting guidance on how to proceed given that one of the other drivers was operating a commercial fleet vehicle with out-of-state plates.', 'phone', 'new_customer'),
    ('New customer called to file a claim involving a three-vehicle chain-reaction collision on I-95, but is unable to provide the police report or the other two drivers'' insurance information, as the responding officer only gave a verbal case number that doesn''t appear in the county records system. The customer states he was rear-ended first and pushed into the vehicle ahead, and is requesting guidance on how to proceed given that the at-fault driver''s insurance carrier has not yet accepted liability and his own policy documents from sign-up two weeks ago haven''t arrived by mail.', 'phone', 'new_customer'),
    ('New customer called to file a claim involving a three-vehicle chain-reaction collision on I-95, but is unable to provide the police report or the other two drivers'' insurance information, stating the responding officer never gave him a copy and the other parties left before exchanging details. The claimant is requesting assistance obtaining the accident report from the state highway patrol while we work to identify the additional carriers involved.', 'phone', 'new_customer'),
    ('New customer called to file a claim involving a three-vehicle chain-reaction collision on I-95, but is unable to provide the police report or the other two drivers'' insurance information, stating the responding officer never gave him a copy and the other parties left the scene before exchanging details. The claimant was transferred between multiple departments during the call as adjusters worked to determine primary liability across three separate insurance carriers with incomplete documentation.', 'phone', 'new_customer'),
    ('New customer called to file a claim involving a three-vehicle chain-reaction collision on I-95, but is unable to provide the police report or the other two drivers'' insurance information, stating the responding officer never gave him a copy and the other parties left the scene before exchanging details. The customer expressed frustration over the complexity of coordinating between multiple unknown insurers and requested guidance on how to proceed without the standard documentation.', 'phone', 'new_customer'),
    ('New customer filed a claim through their agent for a three-vehicle intersection collision involving two other drivers'' insurance carriers, but the police report has not yet been released and the at-fault driver''s policy information was recorded incorrectly at the scene. The agent is working to obtain the corrected police report and coordinate liability documentation between all three insurers to move the claim forward.', 'agent', 'new_customer'),
    ('New customer filed a claim through their agent for a three-vehicle intersection collision involving two other drivers'' insurance carriers, but the police report was never uploaded to the system and the at-fault driver''s policy information provided at the scene appears to belong to a cancelled policy. The agent is working to obtain a certified copy of the accident report from the county sheriff''s office while simultaneously coordinating with the other two insurers to establish liability allocation.', 'agent', 'new_customer'),
    ('New customer filed through their agent reporting a three-vehicle chain-reaction collision at a construction zone, involving two other drivers with out-of-state policies and a municipal road crew, but the police report was never completed at the scene and the construction company''s liability documentation has not yet been located. The agent is working to obtain statements from all parties and coordinate with three separate insurance carriers while the customer awaits a rental vehicle authorization pending verification of coverage.', 'agent', 'new_customer'),
    ('New customer filed through their agent reporting a three-vehicle chain-reaction collision at a construction zone, involving two other drivers with out-of-state policies and a municipal road crew, but the police report was never completed at the scene and the construction company''s liability documentation has not yet been located. The agent is working to obtain statements from all parties and coordinate with three separate insurance carriers while the customer awaits a rental vehicle authorization pending verification of coverage.', 'agent', 'new_customer'),
    ('New customer of three weeks is filing via email for a total loss on a 2021 BMW X5 allegedly stolen from a grocery store parking lot, but the claim was submitted just nine days after the policy was bound and the customer had increased comprehensive coverage limits the day before the reported theft. The claimant has been unable to provide a second key fob and gave conflicting accounts of the vehicle''s mileage when questioned by the adjuster.', 'email', 'new_customer'),
    ('New customer of three weeks submitted an email claim for $47,000 in water damage to a basement home theater system, but the adjuster noted the policy was upgraded to include electronics coverage just four days before the reported loss, and the submitted photos contain metadata showing they were taken in a different state.', 'email', 'new_customer'),
    ('New customer of three weeks submitted an email claim for $47,000 in water damage to a finished basement, but the attached photos contain metadata showing they were taken eleven days before the policy inception date. When contacted for clarification, the claimant provided conflicting accounts of when the flooding occurred and has since stopped responding to the adjuster''s follow-up inquiries.', 'email', 'new_customer'),
    ('New customer of three weeks submitted an email claim for a $14,200 home burglary alleging all electronics and jewelry were stolen while on vacation, but the police report notes no signs of forced entry and the claimant was unable to provide any purchase receipts, photos, or serial numbers for the supposedly stolen items. Neighbors reported no unusual activity during the dates in question, and the claimant''s policy was upgraded to include valuable personal property coverage just five days before the alleged incident.', 'email', 'new_customer'),
    ('New customer of three weeks submitted an email claim for a $47,000 water damage loss to their recently purchased rental property, but the submitted photos contain metadata showing they were taken eleven days before the policy inception date. The claimant has been unresponsive to requests for an in-person inspection and provided conflicting accounts of when the damage was first discovered.', 'email', 'new_customer'),
    ('New customer of three weeks submitted an email claim for a $47,000 water damage loss to their recently purchased rental property, but the submitted photos contain metadata showing they were taken six days before the policy inception date. The claimant has been unresponsive to requests for an independent inspection and has already obtained repair estimates from an out-of-state contractor with no verifiable business license.', 'email', 'new_customer'),
    ('New customer submitted a web claim for a rear-end collision involving four vehicles on Interstate 85, but the police report number provided does not match any records in the local department''s system, and the at-fault driver''s insurance information was not exchanged at the scene. The claimant has been unable to obtain a copy of the accident report despite multiple attempts, complicating liability determination across the involved parties'' respective carriers.', 'web', 'new_customer'),
    ('New customer submitted a web claim for a rear-end collision involving four vehicles on Interstate 85, but the police report number provided does not match any records in the local department''s system, and the at-fault driver''s insurance information was not exchanged at the scene. The claimant has been unable to obtain a copy of the accident report despite multiple attempts, complicating liability determination across the involved parties'' respective carriers.', 'web', 'new_customer'),
    ('New customer submitted a web claim for a rear-end collision involving four vehicles on Interstate 85, but the police report number provided does not match any records in the local department''s system, and two of the other drivers have not yet provided their insurance information or statements.', 'web', 'new_customer'),
    ('New customer submitted a web claim for a rear-end collision involving four vehicles on Interstate 85, but the police report number provided returns no results in the database and the customer has been unable to obtain copies of the other three drivers'' insurance information or contact details. The customer states the at-fault driver''s insurance company has not returned calls and the rental car agency involved is disputing liability for a secondary impact caused by their vehicle''s brake failure.', 'web', 'new_customer'),
    ('New customer submitted a web claim for a rear-end collision involving four vehicles on Interstate 85, but the police report was never filed due to the responding officer''s administrative error, and two of the other drivers'' insurance information was not exchanged at the scene. The claimant has provided dash cam footage and witness contact details but is unable to obtain the official accident report needed to process liability determination across all parties involved.', 'web', 'new_customer'),
    ('New customer submitted a web claim involving a three-vehicle chain-reaction collision at a construction zone, but the police report was never filed due to the responding officer''s administrative error, and the at-fault driver''s insurance carrier is disputing liability while the construction company''s insurer has yet to acknowledge any involvement. The claimant has been unable to obtain a copy of the incident report from the local precinct and is requesting guidance on how to proceed without the supporting documentation needed to establish fault among the multiple parties.', 'web', 'new_customer'),
    ('On the evening of March 12th, my 2023 Mercedes-Benz GLE 450 was struck by a delivery truck that ran a red light at the intersection of Maple Avenue and 5th Street, resulting in severe damage to the driver''s side doors, front quarter panel, and deployed side airbags. I have obtained a copy of the police report and dashcam footage from my vehicle, and I would appreciate expedited handling given my Platinum coverage tier—please contact me at your earliest convenience to arrange an inspection and rental vehicle.', 'email', 'premium'),
    ('On the evening of March 12th, my 2023 Mercedes-Benz GLE 450 was struck by a delivery truck that ran a red light at the intersection of Maple Avenue and Route 9, causing extensive damage to the driver''s side doors, front quarter panel, and deploying both side airbags. I have dashcam footage of the entire incident and a police report (case #2024-07831), and I would appreciate expedited handling given my Platinum coverage tier—please contact my assistant, Laura Chen, at the number on file to coordinate the preferred body shop and luxury rental arrangement.', 'email', 'premium'),
    ('On the evening of March 14th, my 2023 Mercedes-Benz GLE 450 was struck by a delivery truck that ran a red light at the intersection of Maple Drive and Commerce Boulevard, resulting in severe damage to the driver''s side doors, quarter panel, and deployed side curtain airbags. I have obtained a copy of the police report and dashcam footage from my vehicle, and I would appreciate having my dedicated claims advisor contact me at their earliest convenience to arrange for my preferred body shop to begin the assessment.', 'email', 'premium'),
    ('On the evening of March 14th, my 2023 Mercedes-Benz GLE 450 was struck by a delivery truck that ran a red light at the intersection of Maple Drive and Route 9, causing extensive damage to the driver''s side doors, front quarter panel, and deploying both side airbags. I have dashcam footage of the entire incident and a police report (case #2024-07831), and I would appreciate expedited handling given my Platinum coverage tier—please advise on arranging a luxury loaner vehicle while repairs are assessed.', 'email', 'premium'),
    ('On the evening of March 14th, my 2023 Mercedes-Benz GLE 450 was struck by a delivery truck that ran a red light at the intersection of Maple Drive and Route 9, causing extensive damage to the driver''s side doors, front quarter panel, and deploying both side airbags. I have dashcam footage of the entire incident and a police report (case #2024-07831), and I would appreciate expedited handling given my Platinum coverage tier—please contact my assistant, Laura Chen, at the number on file to coordinate the preferred body shop and arrange a luxury loaner vehicle.', 'email', 'premium'),
    ('On the evening of March 14th, my 2023 Mercedes-Benz GLE 450 was struck by a delivery truck that ran a red light at the intersection of Maple Drive and Route 9, causing extensive damage to the driver''s side doors, front quarter panel, and deploying both side airbags. I have dashcam footage of the entire incident and a police report (case #2024-08817), and I would appreciate expedited handling given my Platinum coverage tier—please advise on arranging a luxury loaner vehicle while repairs are assessed.', 'email', 'premium'),
    ('On the evening of March 15th, my 2023 Mercedes-Benz GLE 450 was struck by a delivery truck that ran a red light at the intersection of Maple Avenue and 5th Street, resulting in severe damage to the driver''s side doors, front quarter panel, and deployed side airbags. I have obtained a copy of the police report (case #2024-08817) and dashcam footage from my vehicle confirming the other driver''s fault, and I would appreciate expedited handling given my Platinum policy status.', 'email', 'premium'),
    ('Our VIP client''s 2024 Porsche Taycan sustained significant front-end and undercarriage damage after striking a large piece of truck tire debris on Interstate 95 at highway speed, with the impact also cracking the windshield and disabling multiple sensor systems. The claim was filed through the client''s dedicated account manager, who has arranged priority scheduling at the authorized Porsche collision center and coordinated a comparable luxury loaner vehicle for the interim.', 'agent', 'vip'),
    ('Our VIP client''s 2024 Porsche Taycan sustained significant front-end and undercarriage damage after striking a large piece of truck tire debris on Interstate 95 during rush hour, with the vehicle''s air suspension system also compromised. The claim was filed through the client''s dedicated account agent, who has arranged priority towing to an authorized Porsche service center and coordinated a luxury loaner vehicle for the interim.', 'agent', 'vip'),
    ('Our VIP client''s 2024 Porsche Taycan sustained significant front-end and undercarriage damage after striking a large piece of truck tire debris on Interstate 95 during rush hour, with the vehicle''s air suspension system also compromised. The claim was filed through the client''s dedicated account manager, who has arranged priority towing to an authorized Porsche service center and coordinated a luxury loaner vehicle for the interim.', 'agent', 'vip'),
    ('Our VIP client''s agent filed a claim for a $340,000 custom jewelry collection allegedly stolen during a home renovation, but the contractor on-site reported no signs of forced entry and the client had quietly increased the policy coverage limit by 400% just eleven days before the reported theft. The claimant has declined two requests for an in-person recorded statement, citing overseas travel obligations that cannot be independently verified.', 'agent', 'vip'),
    ('Our VIP client''s agent reported a $340,000 claim for a complete home theater and wine collection loss due to an alleged basement flood, but the plumber''s inspection found no evidence of pipe failure, and the client had quietly increased their personal property coverage by 200% just six weeks before the reported incident. Neighbors also confirmed no water damage was visible from the exterior, and the client declined to allow a follow-up inspection of the premises.', 'agent', 'vip'),
    ('Our VIP client''s vacation home in Aspen was burglarized while they were abroad, resulting in the theft of a curated art collection valued at approximately $1.2 million, along with designer jewelry and a rare vintage watch collection stored in a compromised home safe. The claim was filed through their dedicated private client advisor, who has arranged for an independent art appraiser and gemologist to assist with the valuation process.', 'agent', 'vip'),
    ('Our VIP client''s vacation home in Aspen was burglarized while they were abroad, with thieves taking a curated art collection valued at $1.2 million, a wall safe containing rare watches and jewelry, and several designer furnishings; the claim was filed through their dedicated private client advisor after local authorities completed their initial investigation. The property''s security system had been professionally disabled, and the agent has expedited the assignment of a specialized fine arts adjuster to assess the losses.', 'agent', 'vip'),
    ('Our VIP client''s vacation home in Aspen was burglarized while they were abroad, with thieves taking a curated art collection valued at $1.2 million, several pieces of designer jewelry, and a rare vintage Rolex; the claim was filed through their dedicated private client advisor following discovery by the property management company during a routine check.', 'agent', 'vip'),
    ('Our VIP client, a prominent gallery owner, reported that during a weekend trip to their Aspen residence, thieves bypassed the alarm system and stole a curated collection of rare first-edition books valued at $340,000 along with a vintage Cartier jewelry set from the master bedroom safe. The claim was filed through their dedicated private client advisor, who has arranged for an independent appraiser and is coordinating with local law enforcement for the ongoing investigation.', 'agent', 'vip'),
    ('Our VIP client, a prominent real estate developer, reported that his 2024 Mercedes-AMG GT was rear-ended by a delivery truck while stopped at a red light on Peachtree Street, resulting in significant damage to the rear bumper, trunk, and exhaust system. His dedicated agent filed the claim immediately, noting the client''s request for expedited processing and a luxury loaner vehicle while repairs are completed at the authorized dealership.', 'agent', 'vip'),
    ('Our estate in Hilton Head sustained significant wind and water damage during the recent tropical storm, with the roof partially torn from the west wing, flooding throughout the first and second floors, and extensive damage to the custom millwork, imported marble flooring, and a curated art collection valued at over $2 million. I submitted photos and a preliminary contractor assessment through the online portal and would appreciate expedited handling given the scope of the loss and our longstanding relationship with the company.', 'web', 'vip'),
    ('Our estate sustained significant wind and hail damage during last Thursday''s severe thunderstorm, resulting in destroyed clay roof tiles across the main residence and guest house, shattered skylights in the conservatory, and extensive water intrusion affecting the imported hardwood flooring and custom millwork throughout the east wing. I''ve attached the initial assessment from our property management team and would appreciate having a dedicated adjuster assigned promptly, as we need to coordinate repairs around an upcoming charity gala scheduled at the residence next month.', 'email', 'vip'),
    ('Our estate sustained significant wind and hail damage during last Thursday''s severe thunderstorm, resulting in destroyed clay roof tiles across the main residence and guest house, shattered skylights in the conservatory, and extensive water intrusion affecting the imported hardwood flooring and custom millwork throughout the east wing. I''ve attached the initial assessment from our property manager along with photographs, and I would appreciate having my dedicated claims advisor contact me at their earliest convenience to coordinate inspections.', 'email', 'vip'),
    ('Our estate sustained significant wind and hail damage during last Thursday''s severe thunderstorm, resulting in destroyed clay roof tiles across the main residence and guest house, shattered skylights in the conservatory, and extensive water intrusion affecting the imported hardwood flooring and custom millwork throughout the east wing. I''ve attached the initial assessment from our property manager along with photographs, and I would appreciate having my dedicated claims advisor contact me at their earliest convenience to coordinate inspections.', 'email', 'vip'),
    ('Our estate sustained significant wind and hail damage during last Thursday''s severe thunderstorm, resulting in destroyed clay roof tiles across the main residence and guest house, shattered skylights in the conservatory, and extensive water intrusion affecting the imported hardwood flooring and custom millwork throughout the east wing. I''ve submitted photos and our property manager''s preliminary damage assessment through the portal, and we would appreciate expedited handling given the ongoing exposure to additional weather this week.', 'web', 'vip'),
    ('Our estate sustained significant wind and hail damage during last Thursday''s severe thunderstorm, resulting in destroyed clay roof tiles across the main residence and guest house, shattered skylights in the conservatory, and extensive water intrusion into the second-floor library housing our rare book collection. I''ve attached the initial assessment from our property manager along with photographs, and I would appreciate having a dedicated adjuster assigned promptly given the ongoing exposure to further water damage.', 'email', 'vip'),
    ('Our executive client reported that his Tesla Model S Plaid was struck by a delivery truck that ran a red light at the intersection of Maple Avenue and 5th Street, resulting in severe damage to the driver''s side doors, quarter panel, and suspension components. The claim was submitted through our online portal with attached dashcam footage and a police report, and the client has requested expedited processing along with a premium loaner vehicle while repairs are completed at a Tesla-certified body shop.', 'web', 'vip'),
    ('Our executive client reported through the online portal that his 2024 Mercedes-AMG GT was rear-ended by a delivery truck while stopped at a red light on Lexington Avenue, resulting in significant damage to the rear bumper, trunk lid, and both tail light assemblies. The client has requested expedited handling and a luxury loaner vehicle while repairs are completed at his preferred authorized dealership.', 'web', 'vip'),
    ('Our executive client reported via email that his 2024 Mercedes-AMG GT was rear-ended at a stoplight by a distracted driver, resulting in significant damage to the rear bumper, trunk panel, and both tail light assemblies, and he is requesting expedited processing along with a premium loaner vehicle while repairs are completed. The client also noted persistent neck stiffness following the impact and intends to seek evaluation from his personal physician later this week.', 'email', 'vip');
INSERT INTO {database}.{schema}.DEMO_CLAIMS_UNLABELED (CLAIM_SUMMARY, INCIDENT_CHANNEL, CUSTOMER_SEGMENT)
VALUES
    ('Our executive client reports that his 2024 Mercedes-AMG GT was rear-ended by a delivery truck while stopped at a red light on Park Avenue, resulting in significant damage to the rear bumper, trunk panel, and both tail light assemblies. The claim was submitted through our online portal with attached dashcam footage and a police report, and the client has requested expedited processing along with a premium loaner vehicle while repairs are completed.', 'web', 'vip'),
    ('Our executive client reports that his 2024 Mercedes-AMG GT was rear-ended by a delivery truck while stopped at a red light on Park Avenue, resulting in significant damage to the rear bumper, trunk, and exhaust system, along with deployment of the rear curtain airbags. He emailed his dedicated account manager directly with dashcam footage and a preliminary repair estimate of $38,500 from an authorized Mercedes dealership, requesting expedited processing and a comparable luxury loaner vehicle while repairs are underway.', 'email', 'vip'),
    ('Our executive client reports that his 2024 Mercedes-AMG GT was rear-ended by a delivery truck while stopped at a red light on Park Avenue, resulting in significant damage to the rear bumper, trunk, and exhaust system, and he has emailed requesting expedited processing along with dashcam footage and a repair estimate from his preferred authorized dealership. The client also notes recurring neck pain and has scheduled an appointment with his personal physician for evaluation.', 'email', 'vip'),
    ('Our executive client reports that his 2024 Mercedes-AMG GT was rear-ended by a delivery truck while stopped at a red light on Peachtree Street, resulting in significant damage to the rear bumper, trunk, and exhaust system, along with deployment of the rear headrests. He emailed photos from the scene along with dashcam footage and is requesting expedited processing, noting his longstanding platinum-tier membership and preference for OEM parts only at the authorized dealership.', 'email', 'vip'),
    ('Our executive client reports that his 2024 Porsche Taycan was struck by a delivery truck that ran a red light at the intersection of Maple Avenue and 5th Street, resulting in severe damage to the driver''s side doors and quarter panel, with airbag deployment and a fractured side mirror assembly. He submitted photos and a police report via email and has requested expedited processing, noting he needs a comparable luxury loaner vehicle arranged through our concierge service immediately.', 'email', 'vip'),
    ('Our home was broken into while we were visiting family over the weekend, and the intruders took a 65-inch Samsung television, my wife''s jewelry box containing several heirloom pieces, and approximately $400 in cash from a bedroom drawer. I discovered the break-in when we returned Sunday evening and noticed the back sliding door had been pried open, and I filed a police report that same night before emailing this claim.', 'email', 'standard'),
    ('Our home was broken into while we were visiting family over the weekend, and the intruders took a 65-inch Samsung television, my wife''s jewelry box containing several heirloom pieces, and approximately $400 in cash from a bedroom drawer. We discovered the break-in Sunday evening upon returning home and immediately contacted police, who noted forced entry through a rear sliding glass door; I am submitting this claim along with the police report number and photos of the damage via email for your review.', 'email', 'standard'),
    ('Our home was broken into while we were visiting family over the weekend, and the intruders took a 65-inch Samsung television, my wife''s jewelry box containing several heirloom pieces, and approximately $400 in cash from a bedroom drawer. We discovered the break-in upon returning Sunday evening and noticed the back sliding door had been pried open; a police report has been filed and I am submitting photos of the damage along with receipts for the stolen electronics.', 'email', 'standard'),
    ('Our home was broken into while we were visiting family over the weekend, and the intruders took a 65-inch Samsung television, my wife''s jewelry box containing several heirloom pieces, and approximately $400 in cash from a bedroom drawer. We discovered the break-in upon returning Sunday evening and noticed the back sliding door had been pried open; a police report was filed that night and we are submitting this claim along with photos of the damage and a list of stolen items.', 'email', 'standard'),
    ('Our home was broken into while we were visiting family over the weekend, and the intruders took a 65-inch Samsung television, my wife''s jewelry box containing several heirloom pieces, and approximately $400 in cash from a bedroom drawer. We discovered the break-in upon returning Sunday evening and noticed the back sliding door had been pried open; a police report was filed that night and we are submitting this claim via email along with photos of the damage and a preliminary inventory of stolen items.', 'email', 'standard'),
    ('Our home was broken into while we were visiting family over the weekend, and the intruders took a 65-inch television, my wife''s jewelry box containing several heirloom pieces, and approximately $400 in cash from a bedroom drawer. We discovered the break-in upon returning Sunday evening and noticed the back sliding door had been pried open; a police report was filed that night and we are submitting this claim along with photos of the damage and a preliminary list of stolen items.', 'email', 'standard'),
    ('Our lakefront estate sustained extensive damage when a severe thunderstorm with straight-line winds exceeding 80 mph tore off a significant portion of the slate roof, allowing torrential rain to flood the third-floor master suite, home theater, and wine cellar below. I submitted this claim through your online portal and have already engaged our private restoration contractor to begin emergency tarping, but I need an adjuster dispatched immediately given the scope of interior water damage to custom millwork, rare book collections, and imported Italian marble throughout the affected areas.', 'web', 'vip'),
    ('Our lakefront estate sustained extensive damage when a severe thunderstorm with straight-line winds exceeding 80 mph tore off a significant portion of the slate roof, allowing torrential rain to flood the third-floor master suite, home theater, and wine cellar below. I submitted this claim through your online portal and have attached the structural engineer''s preliminary assessment along with photographs documenting the damage to the custom millwork, imported fixtures, and climate-controlled wine collection valued at approximately $175,000.', 'web', 'vip'),
    ('Our lakefront estate sustained extensive damage when a severe thunderstorm with straight-line winds exceeding 80 mph tore off a significant portion of the slate roof, allowing torrential rain to flood the third-floor master suite, home theater, and wine cellar below. I submitted this claim through your online portal and have attached the structural engineer''s preliminary assessment along with photographs documenting the damage to the property and its custom interior finishes.', 'web', 'vip'),
    ('Our lakefront estate sustained significant wind and hail damage during last Thursday''s severe thunderstorm, with multiple skylights shattered across the main residence and guest house, extensive roof damage to the imported slate tiles, and water intrusion affecting the custom millwork and hardwood flooring throughout the upper level. I''ve already engaged our preferred restoration contractor to begin emergency tarping and moisture mitigation, and I''m submitting this claim along with the initial damage assessment report and photos for your review.', 'web', 'premium'),
    ('Our lakefront estate sustained significant wind and hail damage during last Thursday''s severe thunderstorm, with multiple skylights shattered across the main residence and guest house, extensive roof damage to the imported slate tiles, and water intrusion affecting the custom millwork and hardwood flooring throughout the upper level. I''ve already engaged our preferred restoration contractor to begin emergency tarping and water extraction, and I''m submitting this claim along with the initial damage assessment report and photos for your review.', 'web', 'premium'),
    ('Our lakefront estate sustained significant wind and hail damage during last Thursday''s severe thunderstorm, with multiple skylights shattered across the main residence and guest house, extensive water intrusion affecting the custom hardwood flooring and hand-painted ceiling murals in the great room, and several mature landscaping trees uprooted onto the pool enclosure. I''ve attached the inspection photos and would appreciate having our dedicated claims advisor coordinate the restoration timeline at their earliest convenience.', 'email', 'premium'),
    ('Our lakefront estate sustained significant wind and hail damage during last Thursday''s severe thunderstorm, with multiple skylights shattered across the main residence and guest house, extensive water intrusion affecting the custom hardwood flooring and hand-painted ceiling murals in the great room, and several mature landscaping trees uprooted onto the stone terrace. I''ve already had our property management team tarp the exposed areas and am requesting expedited assignment of a senior adjuster given the scope of interior damage and the need to prevent further deterioration of the restored architectural details.', 'web', 'premium'),
    ('Our lakefront estate sustained significant wind and hail damage during last Thursday''s severe thunderstorm, with multiple skylights shattered, cedar shake roofing torn from the west wing, and extensive water intrusion affecting the great room''s hand-painted ceiling mural and imported Italian marble flooring. I''ve had my property manager secure temporary tarping and am requesting expedited assessment given the ongoing forecast for additional storms this weekend.', 'web', 'vip'),
    ('Our lakefront vacation property in Lake Tahoe sustained catastrophic damage when an unprecedented ice storm caused massive tree limbs to collapse onto the roof, puncturing through to the master suite and great room, while subsequent snowmelt infiltrated the exposed areas and destroyed custom hardwood flooring, a curated art collection, and the home''s integrated smart automation system. I''ve attached the structural engineer''s preliminary report along with photos and am requesting expedited assignment of an adjuster given the ongoing exposure to elements and risk of further interior deterioration.', 'email', 'premium'),
    ('Our lakefront vacation property in Lake Tahoe sustained severe ice dam damage over the winter, causing water infiltration through the roof that destroyed the custom cedar ceiling panels, flooded the upstairs master suite, and warped the heated hardwood flooring throughout the second level, with total restoration costs estimated at $187,000. Claim submitted through the online portal with accompanying drone footage, contractor assessments, and documentation from our property management company who first discovered the damage during a routine inspection.', 'web', 'premium'),
    ('Our long-standing platinum account holder, Dr. Evelyn Marchetti, submitted an email claim reporting that her 2024 Mercedes-Benz S-Class was struck by a delivery truck that ran a red light at the intersection of Elm and 5th Avenue, resulting in extensive damage to the driver''s side doors and quarter panel, with an estimated repair cost exceeding $28,000. Dr. Marchetti has requested expedited processing and a luxury loaner vehicle while repairs are completed at her preferred authorized dealership.', 'email', 'vip'),
    ('Our longtime platinum-tier client reported that his 2024 Mercedes-AMG GT was rear-ended at a stoplight by a distracted driver, resulting in significant damage to the rear bumper, trunk panel, and exhaust system, with an estimated repair cost exceeding $18,000. The claim was submitted through the online portal with attached dashcam footage and a police report, and the client has requested expedited processing along with a premium loaner vehicle while repairs are completed.', 'web', 'vip'),
    ('Our longtime platinum-tier client reported that his 2024 Mercedes-AMG GT was rear-ended at a stoplight by a distracted driver, resulting in significant damage to the rear bumper, trunk panel, and exhaust system, with an estimated repair cost exceeding $18,000. The claim was submitted through the online portal with attached dashcam footage and a police report, and the client has requested expedited processing along with a premium loaner vehicle while repairs are underway.', 'web', 'vip'),
    ('Our platinum policyholder, Dr. Evelyn Marchetti, submitted a detailed email regarding a four-vehicle chain-reaction collision on I-95 involving two commercial trucks from different carriers and an uninsured motorist, but the police report remains unavailable due to an ongoing state police investigation, and the third-party trucking company''s insurer has yet to provide their driver''s employment verification or cargo manifest despite repeated requests. Dr. Marchetti has expressed frustration over the delays impacting her $285,000 claim for her totaled Mercedes S-Class and extensive orthopedic injuries, and our priority response team is coordinating with three separate adjusters and legal counsel to reconstruct liability allocation while awaiting the outstanding documentation.', 'email', 'premium'),
    ('Our platinum-level client''s 6,200 sq ft lakefront estate in Lake Geneva sustained extensive damage when a severe derecho with 95 mph straight-line winds tore off a significant portion of the cedar shake roof, allowing subsequent rainfall to infiltrate the upper two floors and cause widespread water damage to custom millwork, designer furnishings, and a rare book collection valued at over $180,000. The client''s dedicated agent filed the claim immediately and has arranged for emergency tarping services and a preferred restoration contractor to begin mitigation work within hours.', 'agent', 'vip'),
    ('Our platinum-level client''s 6,200 sq ft lakefront estate in Lake Geneva sustained extensive damage when a severe derecho with 95 mph straight-line winds tore off a significant portion of the cedar shake roof, allowing subsequent rainfall to infiltrate the upper two floors, damaging custom millwork, a rare book collection, and the home''s integrated smart systems. The client''s dedicated agent filed the claim immediately and has requested expedited assignment of a senior adjuster given the property''s $4.2M insured value and the need to secure emergency tarping before additional storms forecast later this week.', 'agent', 'vip'),
