INSERT INTO {database}.{schema}.DEMO_CLAIMS_UNLABELED (CLAIM_SUMMARY, INCIDENT_CHANNEL, CUSTOMER_SEGMENT)
VALUES
    ('Our platinum-tier client, a prominent real estate developer, has filed a $2.3 million commercial property damage claim through his dedicated account manager, but processing has stalled because the original signed lease agreements, third-party contractor liability waivers, and subrogation documents from two co-insurers involved in the shared coverage arrangement have not yet been received despite multiple requests. The agent has escalated the matter to the VIP resolution team given the client''s portfolio of eleven active policies and the approaching statutory filing deadline in the involved jurisdiction.', 'agent', 'vip'),
    ('Our platinum-tier client, a prominent real estate developer, has filed a $2.3 million commercial property damage claim through his dedicated agent following a warehouse fire, but the investigation is stalled because the original lease agreements, tenant insurance certificates, and third-party contractor maintenance records were destroyed in the fire itself, while three separate subcontractors and two tenant businesses are each pointing to different parties as the cause of the blaze. The agent is requesting expedited assignment of a senior adjuster and legal counsel to coordinate document reconstruction efforts with the client''s corporate attorney and navigate the multi-party liability disputes before the upcoming mediation deadline.', 'agent', 'vip'),
    ('Our platinum-tier client, a prominent real estate developer, has filed a $2.3 million commercial property damage claim through their dedicated account manager, but processing is stalled due to missing subcontractor liability certificates from three separate firms involved in the renovation project at the time of the water intrusion event. The agent has escalated the case requesting expedited handling given the client''s portfolio value, though coordinating documentation across the general contractor, two subcontractors, and the building management company''s insurer has proven exceptionally challenging.', 'agent', 'vip'),
    ('Our platinum-tier client, a prominent real estate developer, has filed a $2.3 million property damage claim through his dedicated account manager following a construction site collapse, but the general contractor''s certificate of insurance, the subcontractor''s hold-harmless agreement, and the city-issued building permits were all stored in a trailer destroyed during the incident, complicating liability allocation among five involved parties. The agent has escalated the case for expedited document reconstruction and coordinated coverage review across three separate carriers to ensure our VIP client''s claim proceeds without unnecessary delay.', 'agent', 'vip'),
    ('Our platinum-tier client, a prominent real estate developer, submitted an email regarding his $4.2M commercial property damage claim involving three separate contractors, the building management company, and a municipal water authority, but the adjuster has been unable to proceed because the original engineering assessment report and two of the three contractor liability certificates were never attached to any of the correspondence despite multiple follow-up requests. The client has expressed frustration over the delays and indicated he expects dedicated concierge-level handling given his 18-year relationship with our firm and annual premium portfolio exceeding $900K.', 'email', 'vip'),
    ('Our platinum-tier client, a prominent real estate developer, submitted an email regarding his $4.2M commercial property damage claim involving three separate contractors, the building management company, and a municipal water authority, but the adjuster has been unable to proceed because the original signed subrogation waiver from the water authority and two of the three contractors'' certificates of insurance are still outstanding despite multiple requests. The client has expressed frustration that the claim has been open for 47 days and is requesting immediate escalation to senior management, noting that his portfolio includes eight active policies across personal and commercial lines.', 'email', 'vip'),
    ('Our platinum-tier client, a prominent real estate developer, submitted an email regarding his $4.2M commercial property damage claim involving three separate contractors, the building management company, and two subrogation interests, but the adjuster has been unable to proceed because the notarized proof of loss, the independent engineering report, and the signed cooperation agreements from two of the three contractors remain outstanding despite multiple requests over the past six weeks. The client has expressed frustration that his dedicated account executive has not personally intervened to expedite the documentation gathering, and he is requesting an immediate conference call with senior claims leadership to establish a firm timeline for resolution.', 'email', 'vip'),
    ('Our platinum-tier client, a prominent real estate developer, sustained a fractured pelvis and severe lacerations after a scaffolding collapse at a commercial property he was touring with contractors, and his personal agent filed the claim on his behalf while he remains hospitalized at Cedar-Sinai undergoing surgical intervention. The client''s executive assistant has provided all supporting medical documentation and witness statements from three contractors who were present at the time of the incident.', 'agent', 'vip'),
    ('Our platinum-tier client, a prominent real estate developer, sustained a fractured pelvis and severe lacerations after a scaffolding collapse at a construction site he was touring, and his personal agent filed the claim on his behalf while he remains hospitalized at Cedar-Sinai undergoing surgical intervention. The client''s executive assistant has provided all medical documentation and site incident reports, and we have assigned a dedicated senior adjuster per our VIP protocol.', 'agent', 'vip'),
